-- Current deployed functions; no obsolete historical definitions are replayed.

CREATE OR REPLACE FUNCTION private.accept_household_invitation_impl(p_invitation_id uuid, p_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_invite public.household_invitations%rowtype;
  v_token_hash bytea;
  v_user_email text;
begin
  if (select auth.uid()) is null then
    raise exception 'Sign in is required';
  end if;

  select *
    into v_invite
  from public.household_invitations
  where id=p_invitation_id
  for update;

  if not found then
    raise exception 'Invitation not found';
  end if;

  if v_invite.status <> 'pending' then
    raise exception 'Invitation is no longer active';
  end if;

  if v_invite.expires_at <= now() then
    update public.household_invitations
    set status='expired'
    where id=p_invitation_id;
    raise exception 'Invitation has expired';
  end if;

  select token_hash
    into v_token_hash
  from private.household_invitation_tokens
  where invitation_id=p_invitation_id;

  if v_token_hash is null
     or extensions.digest(coalesce(p_token,''),'sha256') <> v_token_hash then
    raise exception 'Invitation token is invalid';
  end if;

  select lower(email)
    into v_user_email
  from auth.users
  where id=(select auth.uid());

  if v_user_email is null or v_user_email <> lower(v_invite.email) then
    raise exception 'Sign in using the email address that received this invitation';
  end if;

  insert into public.household_members(household_id,user_id,role,status)
  values(v_invite.household_id,(select auth.uid()),v_invite.role,'active')
  on conflict(household_id,user_id) do update
  set role=excluded.role,
      status='active';

  update public.household_invitations
  set status='accepted',
      accepted_by=(select auth.uid()),
      accepted_at=now()
  where id=p_invitation_id;

  delete from private.household_invitation_tokens
  where invitation_id=p_invitation_id;

  return v_invite.household_id;
end;
$function$;

CREATE OR REPLACE FUNCTION private.accept_organization_invitation_impl(p_invitation_id uuid, p_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_invitation public.organization_invitations%rowtype;
  v_token_hash text;
  v_user_email text;
begin
  select lower(email)
    into v_user_email
  from auth.users
  where id=(select auth.uid());

  if v_user_email is null then
    raise exception 'Authentication required';
  end if;

  select oi.*
    into v_invitation
  from public.organization_invitations oi
  where oi.id=p_invitation_id
  for update;

  if not found then
    raise exception 'Invitation not found';
  end if;

  select oit.token_hash
    into v_token_hash
  from private.organization_invitation_tokens oit
  where oit.invitation_id=p_invitation_id;

  if v_invitation.status<>'invited'
     or v_invitation.expires_at<=now()
     or lower(v_invitation.email)<>v_user_email
     or v_token_hash is null
     or v_token_hash<>encode(
       extensions.digest(trim(p_token),'sha256'),'hex'
     ) then
    raise exception 'Invitation is invalid, expired, or belongs to another email address';
  end if;

  insert into public.organization_members(
    organization_id,user_id,role,status
  )
  values(
    v_invitation.organization_id,
    (select auth.uid()),
    v_invitation.organization_role,
    'active'
  )
  on conflict(organization_id,user_id) do update
  set role=
        case
          when public.organization_members.role='owner' then 'owner'
          when public.organization_members.role='admin' then 'admin'
          when public.organization_members.role='leader'
               and excluded.role='viewer' then 'leader'
          else excluded.role
        end,
      status='active';

  if v_invitation.group_id is not null then
    insert into public.group_leaders(
      group_id,user_id,role,status
    )
    values(
      v_invitation.group_id,
      (select auth.uid()),
      coalesce(v_invitation.group_role,'leader'),
      'active'
    )
    on conflict(group_id,user_id) do update
    set role=
          case
            when public.group_leaders.role='lead' then 'lead'
            when public.group_leaders.role='leader'
                 and excluded.role='assistant' then 'leader'
            else excluded.role
          end,
        status='active';
  end if;

  update public.organization_invitations
  set status='accepted',
      accepted_by=(select auth.uid()),
      accepted_at=now()
  where id=p_invitation_id;

  return v_invitation.organization_id;
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_daily_metrics_impl(p_days integer)
 RETURNS TABLE(metric_date date, new_households bigint, new_child_profiles bigint, challenges_completed bigint, verses_memorized bigint, books_completed bigint, family_faith_sessions bigint, event_registrations bigint, referrals_attributed bigint, paid_orders bigint, gross_revenue_cents bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with days as (
    select generate_series(
      current_date-(greatest(least(coalesce(p_days,30),180),1)-1),
      current_date,
      '1 day'::interval
    )::date as metric_date
  )
  select
    d.metric_date,
    (select count(*) from public.households h where h.created_at::date=d.metric_date)::bigint,
    (select count(*) from public.child_profiles cp where cp.created_at::date=d.metric_date)::bigint,
    (select count(*) from public.child_challenge_progress ccp where ccp.completed_at::date=d.metric_date and ccp.status='completed')::bigint,
    (select count(*) from public.child_scripture_progress csp where csp.memorized_at::date=d.metric_date and csp.status='memorized')::bigint,
    (select count(*) from public.child_book_progress cbp where cbp.completed_at::date=d.metric_date and cbp.status in ('completed','adventure_completed'))::bigint,
    (select count(*) from public.household_faith_sessions hfs where hfs.completed_at::date=d.metric_date)::bigint,
    (select count(*) from public.event_registrations er where er.registered_at::date=d.metric_date)::bigint,
    (select count(*) from public.referral_attributions ra where ra.attributed_at::date=d.metric_date)::bigint,
    (select count(*) from public.orders o where o.paid_at::date=d.metric_date and o.status in ('paid','processing','partially_fulfilled','fulfilled'))::bigint,
    (select coalesce(sum(o.total_cents),0)::bigint from public.orders o where o.paid_at::date=d.metric_date and o.status in ('paid','processing','partially_fulfilled','fulfilled'))
  from days d
  where private.is_app_admin()
  order by d.metric_date;
$function$;

CREATE OR REPLACE FUNCTION private.admin_get_book_launch_gate_impl()
 RETURNS TABLE(area text, check_key text, title text, severity text, passed boolean, detail text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_app_admin() then
    raise exception 'Adventure Club administrator access required';
  end if;

  return query
  with public_books as (
    select b.id
    from public.books b
    where b.status in ('coming_soon','published')
  ), incomplete as (
    select pb.id
    from public_books pb
    where not exists (select 1 from public.book_power_verses x where x.book_id=pb.id and x.is_required)
       or not exists (select 1 from public.book_devotional_series x where x.book_id=pb.id and x.is_required)
       or not exists (select 1 from public.book_prayer_prompts x where x.book_id=pb.id and x.is_required)
       or not exists (select 1 from public.book_identity_truths x where x.book_id=pb.id and x.is_required)
       or not exists (select 1 from public.book_challenges x where x.book_id=pb.id and x.is_required)
       or not exists (select 1 from public.book_content_links x where x.book_id=pb.id and x.is_required)
  )
  select
    'Books'::text,
    'book_companion_structure'::text,
    'Public books have complete companion pathways'::text,
    'blocker'::text,
    not exists(select 1 from incomplete),
    (select count(*)::text || ' public book(s) missing a required companion component' from incomplete);

  return query
  select
    'Books'::text,
    'book_reward_configuration'::text,
    'Public books have completion rewards configured'::text,
    'blocker'::text,
    not exists(
      select 1 from public.books b
      where b.status in ('coming_soon','published')
        and (coalesce(b.completion_xp,0)<=0 or coalesce(b.adventure_completion_xp,0)<=0)
    ),
    (
      select count(*)::text || ' public book(s) missing book or adventure XP'
      from public.books b
      where b.status in ('coming_soon','published')
        and (coalesce(b.completion_xp,0)<=0 or coalesce(b.adventure_completion_xp,0)<=0)
    );

  return query
  select
    'Membership'::text,
    'book_companion_entitlement'::text,
    'Book Companion access has an active entitlement path'::text,
    'blocker'::text,
    exists(
      select 1
      from public.plan_entitlements pe
      join public.membership_plans mp on mp.id=pe.plan_id
      where pe.entitlement_key='book_companions'
        and mp.is_active=true
    ),
    (
      select count(*)::text || ' active membership plan(s) grant Book Companions'
      from public.plan_entitlements pe
      join public.membership_plans mp on mp.id=pe.plan_id
      where pe.entitlement_key='book_companions'
        and mp.is_active=true
    );
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_get_book_release_gate_impl()
 RETURNS TABLE(area text, check_key text, title text, severity text, passed boolean, detail text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_app_admin() then
    raise exception 'Adventure Club administrator access required';
  end if;

  return query
  select
    'Books'::text,
    'book_release_metadata'::text,
    'Public books have release details and approved cover references'::text,
    'blocker'::text,
    not exists(
      select 1
      from public.books b
      where b.status in ('coming_soon','published')
        and (
          b.release_date is null
          or b.cover_asset_key is null
          or btrim(b.cover_asset_key)=''
          or b.description is null
          or btrim(b.description)=''
        )
    ),
    (
      select count(*)::text || ' public book(s) missing release date, cover reference, or description'
      from public.books b
      where b.status in ('coming_soon','published')
        and (
          b.release_date is null
          or b.cover_asset_key is null
          or btrim(b.cover_asset_key)=''
          or b.description is null
          or btrim(b.description)=''
        )
    );

  return query
  select
    'Books'::text,
    'book_release_status'::text,
    'Released books are no longer marked coming soon'::text,
    'blocker'::text,
    not exists(
      select 1
      from public.books b
      where b.status='coming_soon'
        and b.release_date < current_date
    ),
    (
      select count(*)::text || ' past-release book(s) still marked coming soon'
      from public.books b
      where b.status='coming_soon'
        and b.release_date < current_date
    );
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_get_digital_book_impl(p_book_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if (select auth.uid()) is null or not private.is_content_admin() then
    raise exception 'Content administrator required' using errcode='42501';
  end if;
  return (select manifest from private.digital_book_manifests where book_id=p_book_id);
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_get_digital_book_launch_gate_impl()
 RETURNS TABLE(area text, check_key text, title text, severity text, passed boolean, detail text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prepared integer; missing integer; approved integer; released integer;
begin
  if (select auth.uid()) is null or not private.is_app_admin() then
    raise exception 'Adventure Club administrator access required' using errcode='42501';
  end if;
  select count(*) into prepared from private.digital_book_manifests;
  select count(*) into missing from private.digital_book_manifests m,
    jsonb_array_elements(m.manifest->'pages') page
    where not exists(select 1 from storage.objects o where o.bucket_id='dc-digital-books' and o.name=page->>'path');
  select count(*) into approved from private.digital_book_manifests m
    join public.books b on b.id=m.book_id
    where b.metadata->'digital_reader'=jsonb_build_object('revision',m.manifest->>'revision',
      'sha256',encode(extensions.digest(m.manifest::text,'sha256'),'hex'))
      and exists(select 1 from public.dc_content_reviews r where r.entity_type='book' and r.entity_id=b.id
        and r.status='approved' and r.content_fingerprint=private.dc_entity_fingerprint('book',b.id));
  select count(*) into released from private.digital_book_manifests m where private.digital_book_released(m.book_id);

  return query values
    ('Digital books','digital_book_private_storage','Digital book storage is private','blocker',
      exists(select 1 from storage.buckets b where b.id='dc-digital-books' and b.public=false),
      'Private storage is required to protect full-book page files.'),
    ('Digital books','digital_book_edition_prepared','A digital edition has been prepared','warning',prepared>0,
      prepared::text||' prepared edition(s). Required before offering digital books; prepare corrected images in Books Admin.'),
    ('Digital books','digital_book_page_files','Prepared editions have all page files','warning',prepared>0 and missing=0,
      case when prepared=0 then 'No prepared edition to check. Upload the final page files in Books Admin.'
      else missing::text||' referenced page file(s) missing from private storage. Restore missing files before digital release.' end),
    ('Digital books','digital_book_current_approval','Prepared editions have current human approval','warning',prepared>0 and approved=prepared,
      approved::text||' of '||prepared::text||' edition(s) match current DC Governance approval. Required before digital release.'),
    ('Digital books','digital_book_available','An approved digital edition is released','warning',released>0,
      released::text||' edition(s) pass publication, release-date and governance checks. Required before offering digital books. Signed-in device and Storage tests remain separate.');
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_get_membership_tier_gate_impl()
 RETURNS TABLE(area text, check_key text, title text, severity text, passed boolean, detail text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_app_admin() then
    raise exception 'Adventure Club administrator access required';
  end if;

  return query
  select
    'Membership'::text,
    'two_level_membership'::text,
    'Free and paid membership levels are active'::text,
    'blocker'::text,
    exists(select 1 from public.membership_plans where plan_key='free' and is_active=true)
      and exists(select 1 from public.membership_plans where plan_key='premium' and is_active=true),
    (
      select count(*)::text || ' required membership level(s) active'
      from public.membership_plans
      where plan_key in ('free','premium') and is_active=true
    );

  return query
  select
    'Membership'::text,
    'premium_feature_entitlements'::text,
    'Paid membership includes digital books and the complete challenge library'::text,
    'blocker'::text,
    (
      select count(distinct pe.entitlement_key)=2
      from public.membership_plans mp
      join public.plan_entitlements pe on pe.plan_id=mp.id
      where mp.plan_key='premium'
        and mp.is_active=true
        and pe.entitlement_key in ('digital_books','full_challenge_library')
    )
    and not exists(
      select 1
      from public.membership_plans mp
      join public.plan_entitlements pe on pe.plan_id=mp.id
      where mp.plan_key='free'
        and pe.entitlement_key in ('digital_books','full_challenge_library')
    ),
    'Paid-only feature boundaries enforced by entitlement';

  return query
  select
    'Membership'::text,
    'premium_pricing_approved'::text,
    'Paid membership pricing is approved and configured'::text,
    'warning'::text,
    exists(
      select 1
      from public.membership_plans mp
      where mp.plan_key='premium'
        and mp.is_active=true
        and coalesce(mp.monthly_price_cents,0)>0
    ),
    case
      when exists(
        select 1 from public.membership_plans mp
        where mp.plan_key='premium' and mp.is_active=true and coalesce(mp.monthly_price_cents,0)>0
      ) then 'Monthly paid membership price configured'
      else 'Final paid membership pricing is still pending approval'
    end;

  return query
  select
    'Membership'::text,
    'free_challenge_available'::text,
    'Free members have a published Courage Challenge'::text,
    'blocker'::text,
    exists(
      select 1 from public.challenges c
      where c.status='published'
        and c.access_level='free'
        and (c.available_from is null or c.available_from<=now())
        and (c.available_until is null or c.available_until>now())
    ),
    (
      select count(*)::text || ' free challenge(s) currently available'
      from public.challenges c
      where c.status='published'
        and c.access_level='free'
        and (c.available_from is null or c.available_from<=now())
        and (c.available_until is null or c.available_until>now())
    );

  return query
  select
    'Membership'::text,
    'premium_challenge_available'::text,
    'Paid members have premium challenges available'::text,
    'warning'::text,
    exists(
      select 1 from public.challenges c
      where c.status='published'
        and c.access_level='premium'
        and (c.available_from is null or c.available_from<=now())
        and (c.available_until is null or c.available_until>now())
    ),
    (
      select count(*)::text || ' premium challenge(s) currently available'
      from public.challenges c
      where c.status='published'
        and c.access_level='premium'
        and (c.available_from is null or c.available_from<=now())
        and (c.available_until is null or c.available_until>now())
    );
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_get_production_launch_gate_impl()
 RETURNS TABLE(area text, check_key text, title text, severity text, passed boolean, detail text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_active_products bigint;
  v_queued_notifications bigint;
  v_active_households bigint;
begin
  if not private.is_app_admin() then
    raise exception 'Adventure Club administrator access required';
  end if;

  select count(*) into v_active_products from public.products where status='active';
  select count(*) into v_queued_notifications
    from public.notification_deliveries
    where status='queued' and next_attempt_at<=now();
  select count(*) into v_active_households
    from public.households where status='active';

  return query select 'DC Governance','locked_standards','Locked DC standards active','blocker',
    (select count(*)>=5 from public.dc_governance_standards s where s.is_active=true and s.is_locked=true),
    (select count(*)::text||' locked active standard(s)' from public.dc_governance_standards s where s.is_active=true and s.is_locked=true);

  return query select 'DC Governance','public_content_current_approval','Published creative content has current approval','blocker',
    not exists(
      select 1 from public.dc_governance_review_status s
      where (
        (s.entity_type='book' and s.entity_status in ('coming_soon','published'))
        or (s.entity_type in ('adventure','challenge','content_item','devotional_series','family_faith_guide') and s.entity_status in ('scheduled','published'))
        or (s.entity_type in ('scripture_passage','power_verse','prayer_prompt','identity_truth','event') and s.entity_status='published')
        or (s.entity_type='product' and s.entity_status='active')
      ) and coalesce(s.approval_current,false)=false
    ),
    (select count(*)::text||' public item(s) with stale or missing DC approval'
      from public.dc_governance_review_status s
      where (
        (s.entity_type='book' and s.entity_status in ('coming_soon','published'))
        or (s.entity_type in ('adventure','challenge','content_item','devotional_series','family_faith_guide') and s.entity_status in ('scheduled','published'))
        or (s.entity_type in ('scripture_passage','power_verse','prayer_prompt','identity_truth','event') and s.entity_status='published')
        or (s.entity_type='product' and s.entity_status='active')
      ) and coalesce(s.approval_current,false)=false);

  return query select 'Theology','dear_god_prayers','All structured prayers begin Dear God','blocker',
    not exists(
      select 1 from public.prayer_prompts where prompt_text is not null and btrim(prompt_text) !~* '^Dear[[:space:]]+God[[:space:]]*,'
      union all
      select 1 from public.devotional_days where prayer_prompt is not null and btrim(prayer_prompt)<>'' and btrim(prayer_prompt) !~* '^Dear[[:space:]]+God[[:space:]]*,'
      union all
      select 1 from public.family_faith_guides where prayer_prompt is not null and btrim(prayer_prompt)<>'' and btrim(prayer_prompt) !~* '^Dear[[:space:]]+God[[:space:]]*,'
    ),
    'Prayer database enforcement active';

  return query select 'Privacy','required_consent_policies','Required guardian consent policies are active','blocker',
    exists(select 1 from public.consent_policies cp where cp.is_active=true and cp.required_for_core_service=true),
    (select count(*)::text||' required active consent policy/policies' from public.consent_policies cp where cp.is_active=true and cp.required_for_core_service=true);

  return query select 'Guardian Safety','guardian_pin_coverage','Active family hubs have guardian PIN protection','blocker',
    (v_active_households=0 or not exists(
      select 1 from public.households h where h.status='active'
        and not exists(select 1 from private.household_guardian_security hgs where hgs.household_id=h.id)
    )),
    (select count(*)::text||' active household(s) missing guardian PIN'
      from public.households h where h.status='active'
        and not exists(select 1 from private.household_guardian_security hgs where hgs.household_id=h.id));

  return query select 'Notifications','delivery_cron','Notification delivery worker cron is active','blocker',
    exists(select 1 from cron.job where jobname='dc-notification-delivery-worker' and active=true),
    coalesce((select 'Schedule: '||schedule from cron.job where jobname='dc-notification-delivery-worker' limit 1),'Cron job missing');

  return query select 'Notifications','delivery_worker_recent','Notification worker has a recent successful run','blocker',
    exists(select 1 from public.delivery_worker_runs dwr where dwr.worker_key='notification-delivery-worker' and dwr.status in ('succeeded','partial') and dwr.completed_at>=now()-interval '5 minutes'),
    coalesce((select 'Last run: '||completed_at::text||' · '||status from public.delivery_worker_runs dwr where dwr.worker_key='notification-delivery-worker' order by dwr.started_at desc limit 1),'Worker has never completed');

  return query select 'Notifications','email_provider','Guardian email delivery provider configured','blocker',
    exists(select 1 from public.integration_providers ip where ip.provider_key='email-primary' and ip.status='active' and ip.health_status in ('healthy','degraded')),
    coalesce((select ip.status||' / '||ip.health_status from public.integration_providers ip where ip.provider_key='email-primary' limit 1),'Email provider record missing');

  return query select 'Notifications','push_provider','Guardian push provider configured','warning',
    exists(select 1 from public.integration_providers ip where ip.provider_key='push-primary' and ip.status='active' and ip.health_status in ('healthy','degraded')),
    coalesce((select ip.status||' / '||ip.health_status from public.integration_providers ip where ip.provider_key='push-primary' limit 1),'Push provider record missing');

  return query select 'Notifications','queued_delivery_backlog','No overdue notification delivery backlog','blocker',
    v_queued_notifications=0,
    v_queued_notifications::text||' due queued delivery/deliveries';

  return query select 'Communications','reminder_rules','At least one automated reminder rule configured','warning',
    exists(select 1 from public.notification_reminder_rules nrr where nrr.status='active'),
    (select count(*)::text||' active reminder rule(s)' from public.notification_reminder_rules nrr where nrr.status='active');

  return query select 'Privacy','privacy_cleanup_cron','Privacy export cleanup cron is active','blocker',
    exists(select 1 from cron.job where jobname='dc-privacy-export-cleanup-daily' and active=true),
    coalesce((select 'Schedule: '||schedule from cron.job where jobname='dc-privacy-export-cleanup-daily' limit 1),'Privacy cleanup cron missing');

  return query select 'Commerce','checkout_cleanup_cron','Expired checkout cleanup cron is active','blocker',
    exists(select 1 from cron.job where jobname='dc-checkout-expiry-cleanup' and active=true),
    coalesce((select 'Schedule: '||schedule from cron.job where jobname='dc-checkout-expiry-cleanup' limit 1),'Checkout cleanup cron missing');

  return query select 'Commerce','active_products_governed','All active products have current DC approval','blocker',
    not exists(
      select 1 from public.products p
      left join public.dc_governance_review_status s on s.entity_type='product' and s.entity_id=p.id
      where p.status='active' and coalesce(s.approval_current,false)=false
    ),
    (select count(*)::text||' active product(s) without current approval'
      from public.products p
      left join public.dc_governance_review_status s on s.entity_type='product' and s.entity_id=p.id
      where p.status='active' and coalesce(s.approval_current,false)=false);

  return query select 'Commerce','payment_provider','Hosted payment provider ready when store is active','blocker',
    (v_active_products=0 or exists(
      select 1 from public.integration_providers ip
      where ip.provider_key='commerce-primary' and ip.status='active' and ip.health_status in ('healthy','degraded')
    )),
    case when v_active_products=0 then 'No active products, payment provider not required yet'
      else coalesce((select ip.status||' / '||ip.health_status from public.integration_providers ip where ip.provider_key='commerce-primary' limit 1),'Commerce provider record missing') end;

  return query select 'Commerce','webhook_health','No payment webhook failures in the last 24 hours','blocker',
    not exists(select 1 from public.payment_webhook_events pwe where pwe.status='failed' and pwe.received_at>=now()-interval '24 hours'),
    (select count(*)::text||' failed webhook event(s) in 24h' from public.payment_webhook_events pwe where pwe.status='failed' and pwe.received_at>=now()-interval '24 hours');

  return query select 'Commerce','stale_pending_orders','No stale pending-payment orders','blocker',
    not exists(select 1 from public.orders o where o.status='pending_payment' and o.created_at<now()-interval '1 hour'),
    (select count(*)::text||' stale pending order(s)' from public.orders o where o.status='pending_payment' and o.created_at<now()-interval '1 hour');

  return query select 'Operations','open_privacy_requests','No aging unresolved privacy requests','warning',
    not exists(select 1 from public.data_privacy_requests dpr where dpr.status not in ('completed','canceled','rejected') and dpr.created_at<now()-interval '7 days'),
    (select count(*)::text||' privacy request(s) open longer than 7 days' from public.data_privacy_requests dpr where dpr.status not in ('completed','canceled','rejected') and dpr.created_at<now()-interval '7 days');
end;
$function$;

CREATE OR REPLACE FUNCTION private.admin_platform_snapshot_impl()
 RETURNS TABLE(active_households bigint, active_child_profiles bigint, active_subscriptions bigint, active_organizations bigint, active_groups bigint, challenges_completed_all_time bigint, verses_memorized_all_time bigint, books_completed_all_time bigint, rewards_unlocked_all_time bigint, open_support_tickets bigint, open_privacy_requests bigint, queued_external_notifications bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select
    (select count(*) from public.households where status='active')::bigint,
    (select count(*) from public.child_profiles where status='active')::bigint,
    (select count(*) from public.household_subscriptions where status in ('trialing','active','comped'))::bigint,
    (select count(*) from public.organizations where status='active')::bigint,
    (select count(*) from public.adventure_groups where status='active')::bigint,
    (select count(*) from public.child_challenge_progress where status='completed')::bigint,
    (select count(*) from public.child_scripture_progress where status='memorized')::bigint,
    (select count(*) from public.child_book_progress where status in ('completed','adventure_completed'))::bigint,
    (select count(*) from public.reward_unlocks)::bigint,
    (select count(*) from public.support_tickets where status not in ('resolved','closed'))::bigint,
    (select count(*) from public.data_privacy_requests where status not in ('completed','canceled','rejected'))::bigint,
    (select count(*) from public.notification_deliveries where status='queued')::bigint
  where private.is_app_admin();
$function$;

CREATE OR REPLACE FUNCTION private.admin_prepare_digital_book_impl(p_book_id uuid, p_manifest jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous jsonb; reference jsonb;
begin
  if (select auth.uid()) is null or not private.is_content_admin() then
    raise exception 'Content administrator required' using errcode='42501';
  end if;
  perform 1 from public.books where id=p_book_id for update;
  if not found then raise exception 'Book not found'; end if;
  if not private.digital_book_manifest_valid(p_book_id,p_manifest) then raise exception 'Invalid digital book manifest'; end if;
  if exists (select 1 from jsonb_array_elements(p_manifest->'pages') page
    where not exists (select 1 from storage.objects o where o.bucket_id='dc-digital-books' and o.name=page->>'path')) then
    raise exception 'Upload every page before preparing this digital edition';
  end if;
  select manifest into previous from private.digital_book_manifests where book_id=p_book_id;
  reference:=jsonb_build_object('revision',p_manifest->>'revision','sha256',encode(extensions.digest(p_manifest::text,'sha256'),'hex'));
  if previous=p_manifest and exists (select 1 from public.books where id=p_book_id and metadata->'digital_reader'=reference) then
    return p_manifest->>'revision';
  end if;
  if previous->>'revision'=p_manifest->>'revision' then raise exception 'Changed pages require a new edition revision'; end if;
  insert into private.digital_book_manifests(book_id,manifest) values(p_book_id,p_manifest)
    on conflict(book_id) do update set manifest=excluded.manifest,updated_at=now();
  -- Existing book mutation audit and governance triggers record and invalidate this change.
  update public.books set metadata=jsonb_set(metadata,'{digital_reader}',reference),status='draft' where id=p_book_id;
  return p_manifest->>'revision';
end;
$function$;

