 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from public.child_profiles cp
    join public.household_members hm
      on hm.household_id = cp.household_id
    where cp.id = p_child_profile_id
      and hm.user_id = (select auth.uid())
      and hm.status = 'active'
  );
$function$;

CREATE OR REPLACE FUNCTION private.can_view_event(p_event_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from public.events e
    where e.id=p_event_id
      and e.status='published'
      and (
        private.is_app_admin()
        or (
          e.organization_id is null
          and e.group_id is null
          and (
            e.access_level='free'
            or (e.access_level='member' and private.user_has_household())
            or (e.access_level='premium' and private.user_has_active_entitlement('premium_content'))
          )
        )
        or (e.group_id is not null and (
          private.can_lead_group(e.group_id)
          or exists (
            select 1 from public.child_group_memberships cgm
            where cgm.group_id=e.group_id
              and cgm.status='active'
              and private.can_view_child(cgm.child_profile_id)
          )
        ))
        or (e.organization_id is not null and (
          private.is_org_member(e.organization_id)
          or exists (
            select 1
            from public.adventure_groups ag
            join public.child_group_memberships cgm on cgm.group_id=ag.id
            where ag.organization_id=e.organization_id
              and cgm.status='active'
              and private.can_view_child(cgm.child_profile_id)
          )
        ))
      )
  );
$function$;

CREATE OR REPLACE FUNCTION private.cancel_event_registration_impl(p_registration_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event_id uuid;
begin
  if (select auth.uid()) is null then raise exception 'Guardian household access required'; end if;
  select event_id into v_event_id from public.event_registrations
  where id=p_registration_id and private.can_manage_household(household_id);
  if not found then raise exception 'Registration not found'; end if;
  -- Match registration's lock order so cancellation cannot race its seat count.
  perform 1 from public.events where id=v_event_id for update;
  update public.event_registrations set status='canceled',canceled_at=coalesce(canceled_at,now())
  where id=p_registration_id and private.can_manage_household(household_id)
    and status in ('registered','waitlist','canceled');
  if not found then raise exception 'Registration cannot be canceled'; end if;
end;
$function$;

CREATE OR REPLACE FUNCTION private.child_can_access_adventure(p_child_profile_id uuid, p_adventure_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select (select auth.uid()) is not null and private.can_manage_child(p_child_profile_id)
    and exists (select 1 from public.child_profiles cp
      join public.adventures a on a.id=p_adventure_id
      where cp.id=p_child_profile_id and cp.status='active'
        and (private.is_app_admin() or (
          a.status='published'
          and (a.available_from is null or a.available_from<=now())
          and (a.available_until is null or a.available_until>now())
          and (a.access_level in ('free','member')
            or (a.access_level='premium'
              and private.household_has_active_entitlement(cp.household_id,'premium_content'))))));
$function$;

CREATE OR REPLACE FUNCTION private.child_can_access_challenge(p_child_profile_id uuid, p_challenge_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select (select auth.uid()) is not null and private.can_manage_child(p_child_profile_id)
    and exists (select 1 from public.child_profiles cp
      join public.challenges c on c.id=p_challenge_id
      where cp.id=p_child_profile_id and cp.status='active'
        and (private.is_app_admin() or (
          c.status='published'
          and (c.available_from is null or c.available_from<=now())
          and (c.available_until is null or c.available_until>now())
          and (c.access_level in ('free','member')
            or (c.access_level='premium'
              and private.household_has_active_entitlement(cp.household_id,'full_challenge_library'))))));
$function$;

CREATE OR REPLACE FUNCTION private.child_has_book_companion_access(p_child_profile_id uuid, p_book_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select (select auth.uid()) is not null and private.can_manage_child(p_child_profile_id)
    and exists (select 1 from public.child_profiles cp
      where cp.id=p_child_profile_id and cp.status='active'
        and (private.is_app_admin()
          or private.household_has_active_entitlement(cp.household_id,'book_companions')
          or exists (select 1 from public.household_book_access a
            where a.household_id=cp.household_id and a.book_id=p_book_id
              and a.starts_at<=now() and (a.ends_at is null or a.ends_at>now()))));
