CREATE OR REPLACE FUNCTION private.child_has_digital_book_access(p_child_profile_id uuid, p_book_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select (select auth.uid()) is not null and private.can_manage_child(p_child_profile_id)
    and exists (select 1 from public.child_profiles cp
      where cp.id=p_child_profile_id and cp.status='active' and (
        exists (select 1 from public.household_subscriptions hs
          join public.plan_entitlements pe on pe.plan_id=hs.plan_id
          where hs.household_id=cp.household_id and hs.status in ('trialing','active','comped')
            and (hs.current_period_end is null or hs.current_period_end>now()) and pe.entitlement_key='digital_books')
        or exists (select 1 from public.household_entitlement_grants g
          where g.household_id=cp.household_id and g.entitlement_key='digital_books'
            and g.starts_at<=now() and (g.ends_at is null or g.ends_at>now()))
        or exists (select 1 from public.household_book_access a
          where a.household_id=cp.household_id and a.book_id=p_book_id
            and a.starts_at<=now() and (a.ends_at is null or a.ends_at>now()))
      ));
$function$;

CREATE OR REPLACE FUNCTION private.claim_marketing_leads_for_household_impl(p_household_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := (select auth.uid());
  v_email text;
  v_count integer;
begin
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  if not private.can_manage_household(p_household_id) then
    raise exception 'Guardian household access required';
  end if;

  select lower(email) into v_email
  from auth.users
  where id=v_user_id;

  if v_email is null then
    return 0;
  end if;

  update public.marketing_leads
  set converted_user_id=v_user_id,
      converted_household_id=p_household_id,
      converted_at=coalesce(converted_at,now()),
      metadata=metadata||jsonb_build_object(
        'converted_to_adventure_club',true,
        'converted_at',now()
      )
  where lower(email)=v_email
    and (
      converted_user_id is null
      or converted_user_id=v_user_id
    );

  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION private.create_group_join_code_impl(p_group_id uuid, p_expires_in_days integer, p_max_uses integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_code text;
begin
  if not private.can_lead_group(p_group_id) then
    raise exception 'Group leader access required';
  end if;

  if p_expires_in_days is null or p_expires_in_days < 1 or p_expires_in_days > 90 then
    raise exception 'Expiration must be between 1 and 90 days';
  end if;

  v_code := upper(encode(extensions.gen_random_bytes(5),'hex'));

  insert into private.group_join_codes(
    group_id,code_hash,expires_at,max_uses,created_by
  )
  values(
    p_group_id,
    encode(extensions.digest(v_code,'sha256'),'hex'),
    now()+make_interval(days=>p_expires_in_days),
    p_max_uses,
    (select auth.uid())
  );

  return v_code;
end;
$function$;

CREATE OR REPLACE FUNCTION private.create_guardian_unlock_session_impl(p_household_id uuid, p_pin text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token text;
begin
  if not private.verify_guardian_pin_impl(p_household_id,p_pin) then
    -- A normal NULL response commits the attempt/lockout changes.
    -- Raising here would roll back the verifier's security state.
    return null;
  end if;

  update private.guardian_unlock_sessions
  set revoked_at=clock_timestamp()
  where household_id=p_household_id
    and user_id=(select auth.uid())
    and revoked_at is null;

  v_token := encode(extensions.gen_random_bytes(32),'hex');

  insert into private.guardian_unlock_sessions(
    household_id,user_id,token_hash,expires_at
  )
  values(
    p_household_id,
    (select auth.uid()),
    encode(extensions.digest(v_token,'sha256'),'hex'),
    clock_timestamp()+interval '30 minutes'
  );

  return v_token;
end;
$function$;

CREATE OR REPLACE FUNCTION private.create_household_invitation_impl(p_household_id uuid, p_email text, p_role text, p_expires_days integer)
 RETURNS TABLE(invitation_id uuid, invitation_token text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_token text;
  v_email text;
begin
  if not private.can_manage_household(p_household_id) then
    raise exception 'Guardian access required';
  end if;

  if p_role not in ('parent','guardian','adult') then
    raise exception 'Invalid household role';
  end if;

  v_email := lower(trim(p_email));
  if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'Valid email required';
  end if;

  if exists (
    select 1
    from public.household_members hm
    join auth.users u on u.id=hm.user_id
    where hm.household_id=p_household_id
      and hm.status='active'
      and lower(u.email)=v_email
  ) then
    raise exception 'That adult is already part of this household';
  end if;

  update public.household_invitations
  set status='revoked'
  where household_id=p_household_id
    and lower(email)=v_email
    and status='pending';

  v_token := encode(extensions.gen_random_bytes(24),'hex');

  insert into public.household_invitations(
    household_id,email,role,invited_by,status,expires_at
  )
  values(
    p_household_id,
    v_email,
    p_role,
    (select auth.uid()),
    'pending',
    now() + make_interval(days=>greatest(coalesce(p_expires_days,7),1))
  )
  returning id into v_id;

  insert into private.household_invitation_tokens(invitation_id,token_hash)
  values(v_id,extensions.digest(v_token,'sha256'));

  return query select v_id,v_token;
end;
$function$;

CREATE OR REPLACE FUNCTION private.create_organization_invitation_impl(p_organization_id uuid, p_email text, p_organization_role text, p_group_id uuid, p_group_role text, p_expires_in_days integer)
 RETURNS TABLE(invitation_id uuid, invitation_token text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token text;
  v_invitation_id uuid;
begin
  if not private.can_manage_org(p_organization_id) then
    raise exception 'Organization admin access required';
  end if;

  if p_organization_role not in ('admin','leader','viewer') then
    raise exception 'Unsupported organization role';
  end if;

  if p_organization_role='leader' and p_group_id is null then
    raise exception 'Leader invitations must be assigned to a specific group';
  end if;

  if p_expires_in_days is null
     or p_expires_in_days<1
     or p_expires_in_days>30 then
    raise exception 'Invitation expiration must be between 1 and 30 days';
  end if;

  if p_group_id is not null then
    if not exists(
      select 1
      from public.adventure_groups ag
      where ag.id=p_group_id
        and ag.organization_id=p_organization_id
        and ag.status='active'
    ) then
      raise exception 'Group does not belong to this organization';
    end if;

    if p_group_role is null then
      p_group_role := 'leader';
    end if;
  end if;

  update public.organization_invitations
  set status='canceled'
  where organization_id=p_organization_id
    and lower(email)=lower(trim(p_email))
    and status='invited';

  v_token := encode(extensions.gen_random_bytes(24),'hex');

  insert into public.organization_invitations(
    organization_id,email,organization_role,group_id,group_role,
    status,invited_by,expires_at
  )
  values(
    p_organization_id,
    lower(trim(p_email)),
    p_organization_role,
    p_group_id,
    case when p_group_id is null then null else coalesce(p_group_role,'leader') end,
    'invited',
    (select auth.uid()),
    now()+make_interval(days=>p_expires_in_days)
  )
  returning id into v_invitation_id;

  insert into private.organization_invitation_tokens(
    invitation_id,token_hash
  )
  values(
    v_invitation_id,
    encode(extensions.digest(v_token,'sha256'),'hex')
  );

  return query select v_invitation_id,v_token;
end;
$function$;

CREATE OR REPLACE FUNCTION private.dc_entity_fingerprint(p_entity_type text, p_entity_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb;
begin
  v_payload := private.dc_entity_payload(p_entity_type,p_entity_id);
  if v_payload is null then return null; end if;

  if p_entity_type <> 'product' then
    v_payload := v_payload
      - array['created_at','updated_at','status','available_from','available_until','is_featured']::text[];
  end if;

  return encode(extensions.digest(v_payload::text,'sha256'),'hex');
end;
$function$;

CREATE OR REPLACE FUNCTION private.dc_entity_payload(p_entity_type text, p_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb;
begin
  case p_entity_type
    when 'book' then select to_jsonb(t) into v_payload from public.books t where t.id=p_entity_id;
    when 'adventure' then select to_jsonb(t) into v_payload from public.adventures t where t.id=p_entity_id;
    when 'challenge' then select to_jsonb(t) into v_payload from public.challenges t where t.id=p_entity_id;
    when 'content_item' then select to_jsonb(t) into v_payload from public.content_items t where t.id=p_entity_id;
    when 'scripture_passage' then select to_jsonb(t) into v_payload from public.scripture_passages t where t.id=p_entity_id;
    when 'power_verse' then select to_jsonb(t) into v_payload from public.power_verses t where t.id=p_entity_id;
    when 'devotional_series' then select to_jsonb(t) into v_payload from public.devotional_series t where t.id=p_entity_id;
    when 'prayer_prompt' then select to_jsonb(t) into v_payload from public.prayer_prompts t where t.id=p_entity_id;
    when 'identity_truth' then select to_jsonb(t) into v_payload from public.identity_truths t where t.id=p_entity_id;
    when 'family_faith_guide' then select to_jsonb(t) into v_payload from public.family_faith_guides t where t.id=p_entity_id;
    when 'event' then select to_jsonb(t) into v_payload from public.events t where t.id=p_entity_id;
    when 'media_asset' then select to_jsonb(t) into v_payload from public.media_assets t where t.id=p_entity_id;
    when 'product' then
      select jsonb_build_object(
        'name',t.name,
        'product_type',t.product_type,
        'description',t.description,
        'image_asset_key',t.image_asset_key,
        'metadata',t.metadata
      )
      into v_payload
      from public.products t
      where t.id=p_entity_id;
    else raise exception 'Unsupported DC governance entity type: %',p_entity_type;
  end case;
  return v_payload;
end;
$function$;

CREATE OR REPLACE FUNCTION private.dc_row_fingerprint(p_payload jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select encode(
    extensions.digest(
      (
        p_payload
        - array[
          'created_at','updated_at','status',
          'available_from','available_until',
          'is_featured'
        ]::text[]
      )::text,
      'sha256'
    ),
    'hex'
  );
$function$;

CREATE OR REPLACE FUNCTION private.demote_changed_dc_content()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_public_statuses text[] := string_to_array(tg_argv[0],',');
  v_old_status text := to_jsonb(old)->>'status';
  v_new_status text := to_jsonb(new)->>'status';
begin
  if v_old_status = any(v_public_statuses)
     and v_new_status = any(v_public_statuses)
     and private.dc_row_fingerprint(to_jsonb(old))
       is distinct from private.dc_row_fingerprint(to_jsonb(new)) then
    new.status := 'draft';
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.demote_changed_dc_product()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_old jsonb;
  v_new jsonb;
begin
  if old.status='active' and new.status='active' then
    v_old := jsonb_build_object(
      'name',old.name,'product_type',old.product_type,'description',old.description,
      'image_asset_key',old.image_asset_key,'metadata',old.metadata
    );
    v_new := jsonb_build_object(
      'name',new.name,'product_type',new.product_type,'description',new.description,
      'image_asset_key',new.image_asset_key,'metadata',new.metadata
    );

    if v_old is distinct from v_new then
      new.status := 'draft';
    end if;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.demote_changed_notification_template()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.status='active'
     and new.status='active'
     and private.dc_row_fingerprint(to_jsonb(old))
       is distinct from private.dc_row_fingerprint(to_jsonb(new)) then
    new.status:='draft';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.digital_book_manifest_valid(p_book_id uuid, p_manifest jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare page jsonb; paths text[] := '{}'; prefix text;
begin
  if p_book_id is null or p_manifest is null or jsonb_typeof(p_manifest) <> 'object'
    or coalesce(p_manifest->>'revision','') !~ '^[a-z0-9][a-z0-9-]{0,63}$'
    or jsonb_typeof(p_manifest->'pages') is distinct from 'array' then return false; end if;
  if jsonb_array_length(p_manifest->'pages') not between 1 and 300 then return false; end if;
  prefix := p_book_id::text || '/' || (p_manifest->>'revision') || '/';
  for page in select value from jsonb_array_elements(p_manifest->'pages') loop
    if jsonb_typeof(page) <> 'object'
      or jsonb_typeof(page->'path') is distinct from 'string'
      or left(page->>'path',length(prefix)) <> prefix
      or substring(page->>'path' from length(prefix)+1) !~ '^[a-zA-Z0-9_-]+\.(png|jpg|jpeg|webp)$'
      or jsonb_typeof(page->'alt') is distinct from 'string'
      or length(btrim(page->>'alt')) not between 1 and 10000
      or (page->>'alt') like '%' || chr(8212) || '%'
      or (page->>'path') = any(paths) then return false; end if;
    paths := array_append(paths,page->>'path');
  end loop;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION private.digital_book_object_readable(p_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target_book_id uuid;
begin
  if (select auth.uid()) is null then return false; end if;
  begin target_book_id:=split_part(p_path,'/',1)::uuid;
  exception when invalid_text_representation then return false; end;
  return private.digital_book_released(target_book_id)
    and exists (select 1 from private.digital_book_manifests m, jsonb_array_elements(m.manifest->'pages') page
      where m.book_id=target_book_id and page->>'path'=p_path)
    and exists (select 1 from public.child_profiles cp
      join public.household_members hm on hm.household_id=cp.household_id
      where hm.user_id=(select auth.uid()) and hm.status='active' and hm.role in ('owner','parent','guardian')
        and cp.status='active' and private.child_has_digital_book_access(cp.id,target_book_id));
end;
$function$;

CREATE OR REPLACE FUNCTION private.digital_book_released(p_book_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1 from public.books b join private.digital_book_manifests m on m.book_id=b.id
    where b.id=p_book_id and b.status='published'
      and (b.release_date is null or b.release_date<=current_date)
      and b.metadata->'digital_reader'=jsonb_build_object('revision',m.manifest->>'revision',
        'sha256',encode(extensions.digest(m.manifest::text,'sha256'),'hex'))
      and exists (select 1 from public.dc_content_reviews r
        where r.entity_type='book' and r.entity_id=b.id and r.status='approved'
          and r.content_fingerprint=private.dc_entity_fingerprint('book',b.id))
  );
$function$;

CREATE OR REPLACE FUNCTION private.dispatch_automated_notification_reminders()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rule record;
  v_template public.notification_templates%rowtype;
  v_count integer := 0;
  v_inserted_count integer;
begin
  for v_rule in
    select nrr.*
    from public.notification_reminder_rules nrr
    where nrr.status='active'
    order by nrr.created_at
  loop
    select *
      into v_template
    from public.notification_templates
    where id=v_rule.template_id
      and status='active';

    if not found then
      continue;
    end if;

    if v_rule.rule_type='event_upcoming' then
      with recipients as (
        select distinct on(hm.user_id,e.id)
          e.id as source_id,
          hm.user_id,
          hm.household_id
        from public.events e
        join public.event_registrations er on er.event_id=e.id
        join public.household_members hm on hm.household_id=er.household_id
        where e.status='published'
          and e.starts_at>now()
          and e.starts_at<=now()+make_interval(mins=>v_rule.lead_minutes)
          and er.status in ('registered','waitlist')
          and hm.status='active'
          and hm.role in ('owner','parent','guardian')
          and (
            v_rule.organization_id is null
            or e.organization_id=v_rule.organization_id
          )
          and (
            v_rule.group_id is null
            or e.group_id=v_rule.group_id
          )
        order by hm.user_id,e.id,hm.created_at
      ),
      new_logs as (
        insert into public.automated_notification_log(
          rule_id,source_type,source_id,user_id,household_id
        )
        select
          v_rule.id,
          'event',
          r.source_id,
          r.user_id,
          r.household_id
        from recipients r
        on conflict(rule_id,source_type,source_id,user_id) do nothing
        returning id,source_id,user_id,household_id
      ),
      inserted_notifications as (
        insert into public.user_notifications(
          user_id,household_id,notification_type,title,body,deep_link,
          priority,metadata
        )
        select
          nl.user_id,
          nl.household_id,
          v_template.notification_type,
          v_template.title,
          v_template.body,
          v_template.deep_link,
          v_template.priority,
          jsonb_build_object(
            'reminder_rule_id',v_rule.id,
            'source_type','event',
            'source_id',nl.source_id,
            'delivery_channels',to_jsonb(v_rule.delivery_channels)
          )
        from new_logs nl
        returning id,user_id,(metadata->>'source_id')::uuid as source_id
      ),
      linked as (
        update public.automated_notification_log anl
        set notification_id=n.id
        from inserted_notifications n
        where anl.rule_id=v_rule.id
          and anl.source_type='event'
          and anl.user_id=n.user_id
          and anl.source_id=n.source_id
          and anl.notification_id is null
        returning anl.id
      )
      select count(*) into v_inserted_count from linked;

      v_count := v_count + coalesce(v_inserted_count,0);

    elsif v_rule.rule_type='group_challenge_due' then
      with recipients as (
        select distinct on(hm.user_id,gca.id)
          gca.id as source_id,
          hm.user_id,
          hm.household_id
        from public.group_challenge_assignments gca
        join public.adventure_groups ag on ag.id=gca.group_id
        join public.child_group_memberships cgm
          on cgm.group_id=gca.group_id
        join public.child_profiles cp on cp.id=cgm.child_profile_id
        join public.household_members hm on hm.household_id=cp.household_id
        where gca.due_at is not null
          and gca.due_at>now()
          and gca.due_at<=now()+make_interval(mins=>v_rule.lead_minutes)
          and ag.status='active'
          and cgm.status='active'
          and cp.status='active'
          and hm.status='active'
          and hm.role in ('owner','parent','guardian')
          and (
            v_rule.organization_id is null
            or ag.organization_id=v_rule.organization_id
          )
          and (
            v_rule.group_id is null
            or gca.group_id=v_rule.group_id
          )
          and not exists (
            select 1
            from public.child_challenge_progress ccp
            where ccp.child_profile_id=cp.id
              and ccp.challenge_id=gca.challenge_id
              and ccp.status='completed'
          )
        order by hm.user_id,gca.id,hm.created_at
      ),
      new_logs as (
        insert into public.automated_notification_log(
          rule_id,source_type,source_id,user_id,household_id
        )
        select
          v_rule.id,
          'group_challenge',
          r.source_id,
          r.user_id,
          r.household_id
        from recipients r
        on conflict(rule_id,source_type,source_id,user_id) do nothing
        returning id,source_id,user_id,household_id
      ),
      inserted_notifications as (
        insert into public.user_notifications(
          user_id,household_id,notification_type,title,body,deep_link,
          priority,metadata
        )
        select
          nl.user_id,
          nl.household_id,
          v_template.notification_type,
          v_template.title,
          v_template.body,
          v_template.deep_link,
          v_template.priority,
          jsonb_build_object(
            'reminder_rule_id',v_rule.id,
            'source_type','group_challenge',
            'source_id',nl.source_id,
            'delivery_channels',to_jsonb(v_rule.delivery_channels)
          )
        from new_logs nl
        returning id,user_id,(metadata->>'source_id')::uuid as source_id
      ),
      linked as (
        update public.automated_notification_log anl
        set notification_id=n.id
        from inserted_notifications n
        where anl.rule_id=v_rule.id
          and anl.source_type='group_challenge'
          and anl.user_id=n.user_id
          and anl.source_id=n.source_id
          and anl.notification_id is null
        returning anl.id
      )
      select count(*) into v_inserted_count from linked;

      v_count := v_count + coalesce(v_inserted_count,0);
    end if;
  end loop;

  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION private.dispatch_due_notification_campaigns()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_campaign record;
  v_template public.notification_templates%rowtype;
  v_count integer := 0;
  v_inserted integer;
begin
  for v_campaign in
    select nc.*
    from public.notification_campaigns nc
    where nc.status='scheduled'
      and nc.scheduled_at<=now()
    order by nc.scheduled_at
    for update skip locked
  loop
    begin
      update public.notification_campaigns
      set status='processing',
          error_message=null
      where id=v_campaign.id;

      select *
        into v_template
      from public.notification_templates
      where id=v_campaign.template_id
        and status='active';

      if not found then
        raise exception 'Notification template is not active';
      end if;

      if v_campaign.audience_type='all_guardians' then
        insert into public.notification_campaign_recipients(
          campaign_id,user_id,household_id
        )
        select distinct on(hm.user_id)
          v_campaign.id,
          hm.user_id,
          hm.household_id
        from public.household_members hm
        where hm.status='active'
          and hm.role in ('owner','parent','guardian')
        order by hm.user_id,hm.created_at
        on conflict(campaign_id,user_id) do nothing;

      elsif v_campaign.audience_type='plan_guardians' then
        insert into public.notification_campaign_recipients(
          campaign_id,user_id,household_id
        )
        select distinct on(hm.user_id)
          v_campaign.id,
          hm.user_id,
          hm.household_id
        from public.household_subscriptions hs
        join public.household_members hm
          on hm.household_id=hs.household_id
        where hs.plan_id=v_campaign.membership_plan_id
          and hs.status in ('trialing','active','comped','past_due')
          and hm.status='active'
          and hm.role in ('owner','parent','guardian')
        order by hm.user_id,hm.created_at
        on conflict(campaign_id,user_id) do nothing;

      elsif v_campaign.audience_type='household_guardians' then
        insert into public.notification_campaign_recipients(
          campaign_id,user_id,household_id
        )
        select distinct
          v_campaign.id,
          hm.user_id,
          hm.household_id
        from public.household_members hm
        where hm.household_id=v_campaign.household_id
          and hm.status='active'
          and hm.role in ('owner','parent','guardian')
        on conflict(campaign_id,user_id) do nothing;

      elsif v_campaign.audience_type='group_guardians' then
        insert into public.notification_campaign_recipients(
          campaign_id,user_id,household_id
        )
        select distinct on(hm.user_id)
          v_campaign.id,
          hm.user_id,
          hm.household_id
        from public.child_group_memberships cgm
        join public.child_profiles cp on cp.id=cgm.child_profile_id
        join public.household_members hm on hm.household_id=cp.household_id
        where cgm.group_id=v_campaign.group_id
          and cgm.status='active'
          and cp.status='active'
          and hm.status='active'
          and hm.role in ('owner','parent','guardian')
        order by hm.user_id,hm.created_at
        on conflict(campaign_id,user_id) do nothing;

      elsif v_campaign.audience_type='organization_guardians' then
        insert into public.notification_campaign_recipients(
          campaign_id,user_id,household_id
        )
        select distinct on(hm.user_id)
          v_campaign.id,
          hm.user_id,
          hm.household_id
        from public.adventure_groups ag
        join public.child_group_memberships cgm on cgm.group_id=ag.id
        join public.child_profiles cp on cp.id=cgm.child_profile_id
        join public.household_members hm on hm.household_id=cp.household_id
        where ag.organization_id=v_campaign.organization_id
          and ag.status='active'
          and cgm.status='active'
          and cp.status='active'
          and hm.status='active'
          and hm.role in ('owner','parent','guardian')
        order by hm.user_id,hm.created_at
        on conflict(campaign_id,user_id) do nothing;

      elsif v_campaign.audience_type='event_guardians' then
        insert into public.notification_campaign_recipients(
          campaign_id,user_id,household_id
        )
        select distinct on(hm.user_id)
          v_campaign.id,
          hm.user_id,
          hm.household_id
        from public.event_registrations er
        join public.household_members hm on hm.household_id=er.household_id
        where er.event_id=v_campaign.event_id
          and er.status in ('registered','waitlist')
          and hm.status='active'
          and hm.role in ('owner','parent','guardian')
        order by hm.user_id,hm.created_at
        on conflict(campaign_id,user_id) do nothing;
      end if;

      with inserted as (
        insert into public.user_notifications(
          user_id,
          household_id,
          notification_type,
          title,
          body,
          deep_link,
          priority,
          metadata
        )
        select
          ncr.user_id,
          ncr.household_id,
          v_template.notification_type,
          v_template.title,
          v_template.body,
          v_template.deep_link,
          v_template.priority,
          jsonb_build_object(
            'campaign_id',v_campaign.id,
            'template_id',v_template.id,
            'delivery_channels',to_jsonb(v_campaign.delivery_channels)
          )
        from public.notification_campaign_recipients ncr
        where ncr.campaign_id=v_campaign.id
          and ncr.notification_id is null
        returning id,user_id
      )
      update public.notification_campaign_recipients ncr
      set notification_id=i.id
      from inserted i
      where ncr.campaign_id=v_campaign.id
        and ncr.user_id=i.user_id
        and ncr.notification_id is null;

      get diagnostics v_inserted = row_count;

      update public.notification_campaigns
      set status='sent',
          sent_at=now(),
          recipients_count=(
            select count(*)
            from public.notification_campaign_recipients ncr
            where ncr.campaign_id=v_campaign.id
          )
      where id=v_campaign.id;

      v_count := v_count+1;

    exception when others then
      update public.notification_campaigns
      set status='failed',
          error_message=sqlerrm
      where id=v_campaign.id;
    end;
  end loop;

  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enforce_child_adventure_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if (select auth.uid()) is not null
    and not private.child_can_access_adventure(new.child_profile_id,new.adventure_id)
  then raise exception 'Adventure access required'; end if;
  return new;
end;
$function$;

