$function$;

CREATE OR REPLACE FUNCTION private.enforce_dc_prayer_opening()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_field text := tg_argv[0];
  v_prayer text;
begin
  v_prayer := to_jsonb(new) ->> v_field;

  if v_prayer is not null and btrim(v_prayer) <> '' then
    if btrim(v_prayer) ~* '^Dear[[:space:]]+Jesus([,[:space:]]|$)' then
      raise exception 'Dustin Courageous prayers must be addressed to God, not Jesus. Begin with "Dear God,".';
    end if;

    if btrim(v_prayer) !~* '^Dear[[:space:]]+God[[:space:]]*,' then
      raise exception 'Dustin Courageous prayers must begin with "Dear God,".';
    end if;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.enforce_dc_publish_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_entity_type text := tg_argv[0];
  v_publish_statuses text[] := string_to_array(tg_argv[1],',');
  v_new_status text;
begin
  v_new_status := to_jsonb(new)->>'status';

  if v_new_status = any(v_publish_statuses) then
    if not private.has_approved_dc_review(v_entity_type,new.id) then
      raise exception 'DC governance review is required before publishing this %.',replace(v_entity_type,'_',' ');
    end if;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.evaluate_badges_after_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status = 'completed'
     and (tg_op = 'INSERT' or old.status is distinct from 'completed') then
    perform private.evaluate_child_badges(new.child_profile_id);
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.evaluate_child_badges(p_child_profile_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_household_id uuid;
  v_child_name text;
  v_rule record;
  v_value bigint;
  v_award_id uuid;
begin
  select cp.household_id, cp.display_name
    into v_household_id, v_child_name
  from public.child_profiles cp
  where cp.id = p_child_profile_id;

  if v_household_id is null then
    return;
  end if;

  for v_rule in
    select br.*, b.name as badge_name
    from public.badge_rules br
    join public.badges b on b.id = br.badge_id
    where br.is_active = true
      and b.is_active = true
      and br.rule_type <> 'manual'
  loop
    v_value := 0;

    case v_rule.rule_type
      when 'xp_threshold' then
        select coalesce(sum(x.points),0)
        into v_value
        from public.xp_ledger x
        where x.child_profile_id=p_child_profile_id;

      when 'challenge_count' then
        select count(*)
        into v_value
        from public.child_challenge_progress ccp
        where ccp.child_profile_id=p_child_profile_id
          and ccp.status='completed';

      when 'adventure_count' then
        select count(*)
        into v_value
        from public.child_adventure_progress cap
        where cap.child_profile_id=p_child_profile_id
          and cap.status='completed';

      when 'streak' then
        select coalesce(cs.current_count,0)
        into v_value
        from public.child_streaks cs
        where cs.child_profile_id=p_child_profile_id
          and cs.streak_key=v_rule.streak_key;

        v_value := coalesce(v_value,0);

      when 'challenge_type_count' then
        select count(*)
        into v_value
        from public.child_challenge_progress ccp
        join public.challenges c on c.id=ccp.challenge_id
        where ccp.child_profile_id=p_child_profile_id
          and ccp.status='completed'
          and c.challenge_type=v_rule.challenge_type;

      when 'token_threshold' then
        select coalesce(sum(atl.amount),0)
        into v_value
        from public.achievement_token_ledger atl
        where atl.child_profile_id=p_child_profile_id
          and atl.token_type=v_rule.token_type;

      when 'activity_event_count' then
        select count(*)
        into v_value
        from public.child_activity_events cae
        where cae.child_profile_id=p_child_profile_id
          and cae.event_type=v_rule.activity_event_type;

      else
        v_value := 0;
    end case;

    if v_value >= v_rule.threshold_value then
      v_award_id := null;

      insert into public.badge_awards(
        child_profile_id,badge_id,source_type,source_id,metadata
      )
      values(
        p_child_profile_id,
        v_rule.badge_id,
        'badge_rule',
        v_rule.id,
        jsonb_build_object(
          'rule_type',v_rule.rule_type,
          'threshold_value',v_rule.threshold_value,
          'value_at_award',v_value
        )
      )
      on conflict(child_profile_id,badge_id) do nothing
      returning id into v_award_id;

      if v_award_id is not null then
        insert into public.child_activity_events(
          child_profile_id,household_id,event_type,title,description,source_type,source_id
        )
        values(
          p_child_profile_id,v_household_id,'badge_earned',
          'New badge earned',v_rule.badge_name,'badge',v_rule.badge_id
        );

        insert into public.user_notifications(
          user_id,household_id,child_profile_id,notification_type,title,body,deep_link,metadata
        )
        select
          hm.user_id,
          v_household_id,
          p_child_profile_id,
          'badge_earned',
          'New badge earned!',
          coalesce(v_child_name,'Your child') || ' earned the ' || v_rule.badge_name || ' badge.',
          '/family/children/' || p_child_profile_id::text || '/badges',
          jsonb_build_object('badge_id',v_rule.badge_id,'badge_rule_id',v_rule.id)
        from public.household_members hm
        where hm.household_id=v_household_id
          and hm.status='active'
          and hm.role in ('owner','parent','guardian');
      end if;
    end if;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION private.event_audience_allows_registration(p_event_id uuid, p_household_id uuid, p_child_profile_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select (select auth.uid()) is not null
   and private.can_manage_household(p_household_id)
   and (p_child_profile_id is null or exists (
     select 1 from public.child_profiles cp where cp.id=p_child_profile_id
       and cp.household_id=p_household_id and cp.status='active'))
   and exists (
     select 1 from public.events e where e.id=p_event_id and e.status='published'
       and case
         when e.group_id is not null then exists (
           select 1 from public.adventure_groups ag
           join public.organizations o on o.id=ag.organization_id
           join public.child_group_memberships cgm on cgm.group_id=ag.id
           join public.child_profiles cp on cp.id=cgm.child_profile_id
           where ag.id=e.group_id and ag.status='active' and o.status='active'
             and (e.organization_id is null or e.organization_id=ag.organization_id)
             and cgm.status='active' and cp.status='active'
             and cp.household_id=p_household_id
             and (p_child_profile_id is null or cp.id=p_child_profile_id))
         when e.organization_id is not null then exists (
           select 1 from public.organizations o where o.id=e.organization_id and o.status='active'
             and ((p_child_profile_id is null and private.is_org_member(o.id))
               or exists (
                 select 1 from public.adventure_groups ag
                 join public.child_group_memberships cgm on cgm.group_id=ag.id
                 join public.child_profiles cp on cp.id=cgm.child_profile_id
                 where ag.organization_id=o.id and ag.status='active'
                   and cgm.status='active' and cp.status='active'
                   and cp.household_id=p_household_id
                   and (p_child_profile_id is null or cp.id=p_child_profile_id))))
         else true
       end);
$function$;

CREATE OR REPLACE FUNCTION private.expire_checkout_sessions()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_count integer;
begin
  with expired as (
    update public.checkout_sessions
    set status='expired',updated_at=now()
    where status in ('created','provider_pending')
      and expires_at<=now()
    returning id,order_id
  ),
  released as (
    update public.inventory_reservations ir
    set released_at=now()
    from expired e
    where ir.checkout_session_id=e.id
      and ir.released_at is null
    returning ir.id
  ),
  canceled as (
    update public.orders o
    set status='canceled',canceled_at=now(),updated_at=now()
    from expired e
    where o.id=e.order_id
      and o.status in ('draft','pending_payment')
    returning o.id
  )
  select count(*)::integer into v_count from expired;

  return coalesce(v_count,0);
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_digital_book_impl(p_child_profile_id uuid, p_book_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare content jsonb; position integer;
begin
  if (select auth.uid()) is null or not private.can_manage_child(p_child_profile_id)
    or not exists (select 1 from public.child_profiles where id=p_child_profile_id and status='active') then
    raise exception 'Child access denied' using errcode='42501';
  end if;
  if not private.digital_book_released(p_book_id) then return jsonb_build_object('availability','unavailable'); end if;
  if not private.child_has_digital_book_access(p_child_profile_id,p_book_id) then return jsonb_build_object('availability','locked'); end if;
  select manifest into content from private.digital_book_manifests where book_id=p_book_id;
  select page_number into position from public.child_book_reading_positions
    where child_profile_id=p_child_profile_id and book_id=p_book_id and revision=content->>'revision';
  return jsonb_build_object('availability','ready','revision',content->>'revision','pages',content->'pages',
    'page_number',least(coalesce(position,1),jsonb_array_length(content->'pages')));
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_group_progress_summary_impl(p_group_id uuid, p_challenge_id uuid)
 RETURNS TABLE(active_children bigint, completed_children bigint, completion_percent integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with members as (
    select cgm.child_profile_id
    from public.child_group_memberships cgm
    where cgm.group_id=p_group_id
      and cgm.status='active'
  )
  select
    count(*)::bigint,
    count(*) filter (
      where exists (
        select 1
        from public.child_challenge_progress ccp
        where ccp.child_profile_id=members.child_profile_id
          and ccp.challenge_id=p_challenge_id
          and ccp.status='completed'
      )
    )::bigint,
    case
      when count(*)=0 then 0
      else floor(
        count(*) filter (
          where exists (
            select 1
            from public.child_challenge_progress ccp
            where ccp.child_profile_id=members.child_profile_id
              and ccp.challenge_id=p_challenge_id
              and ccp.status='completed'
          )
        )::numeric / count(*)::numeric * 100
      )::integer
    end
  from members
  where private.can_lead_group(p_group_id);
$function$;

CREATE OR REPLACE FUNCTION private.get_group_roster_impl(p_group_id uuid)
 RETURNS TABLE(child_profile_id uuid, display_name text, membership_status text, joined_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select
    cp.id,
    cp.display_name,
    cgm.status,
    cgm.joined_at
  from public.child_group_memberships cgm
  join public.child_profiles cp on cp.id=cgm.child_profile_id
  where cgm.group_id=p_group_id
    and cgm.status='active'
    and private.can_lead_group(p_group_id)
  order by cp.display_name;
$function$;

CREATE OR REPLACE FUNCTION private.get_household_adults_impl(p_household_id uuid)
 RETURNS TABLE(user_id uuid, role text, status text, email text, display_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_household_member(p_household_id) then
    raise exception 'Household access required';
  end if;

  return query
  select
    hm.user_id,
    hm.role,
    hm.status,
    u.email::text,
    coalesce(p.display_name, nullif(trim(concat_ws(' ',p.first_name,p.last_name)),''))
  from public.household_members hm
  join auth.users u on u.id=hm.user_id
  left join public.profiles p on p.id=hm.user_id
  where hm.household_id=p_household_id
    and hm.status='active'
  order by
    case hm.role when 'owner' then 0 when 'parent' then 1 when 'guardian' then 2 else 3 end,
    u.email;
end;
$function$;

CREATE OR REPLACE FUNCTION private.get_or_create_referral_code_impl(p_household_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_code text;
begin
  if not private.can_manage_household(p_household_id) then
    raise exception 'Guardian household access required';
  end if;

  select code into v_code
  from public.referral_codes
  where household_id=p_household_id and is_active=true;

  if v_code is not null then
    return v_code;
  end if;

  loop
    v_code := upper(substr(encode(extensions.gen_random_bytes(6),'hex'),1,10));
    exit when not exists(select 1 from public.referral_codes where code=v_code);
  end loop;

  insert into public.referral_codes(household_id,code,created_by)
  values(p_household_id,v_code,(select auth.uid()));

  return v_code;
end;
$function$;

CREATE OR REPLACE FUNCTION private.guardian_pin_status_impl(p_household_id uuid)
 RETURNS TABLE(configured boolean, locked_until timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_household_member(p_household_id) then
    raise exception 'Household access required';
  end if;

  return query
  select
    (hgs.household_id is not null) as configured,
    hgs.locked_until
  from (select p_household_id as household_id) input
  left join private.household_guardian_security hgs
    on hgs.household_id = input.household_id;
end;
$function$;

CREATE OR REPLACE FUNCTION private.guardian_unlock_session_valid(p_household_id uuid, p_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  if not private.can_manage_household(p_household_id) then return false; end if;
  -- Check and touch the session in one statement. A concurrent revocation is
  -- rechecked after its row lock, and expiry uses wall time rather than tx start.
  update private.guardian_unlock_sessions gus
  set last_used_at=clock_timestamp()
  where gus.household_id=p_household_id
    and gus.user_id=(select auth.uid())
    and gus.revoked_at is null
    and gus.expires_at>clock_timestamp()
    and gus.token_hash=encode(extensions.digest(trim(p_token),'sha256'),'hex')
  returning gus.id into v_id;
  return v_id is not null;
end;
$function$;

CREATE OR REPLACE FUNCTION private.handle_new_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.profiles (id, first_name, last_name, display_name)
  values (
    new.id,
    nullif(new.raw_user_meta_data ->> 'first_name', ''),
    nullif(new.raw_user_meta_data ->> 'last_name', ''),
    nullif(coalesce(new.raw_user_meta_data ->> 'display_name', new.raw_user_meta_data ->> 'name'), '')
  )
  on conflict (id) do nothing;
  return new;
end;
$function$;

