CREATE OR REPLACE FUNCTION private.join_child_to_group_impl(p_code text, p_child_profile_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_join_code private.group_join_codes%rowtype;
  v_group_id uuid;
  v_household_id uuid;
  v_policy_version text;
begin
  if (select auth.uid()) is null or not private.can_manage_child(p_child_profile_id) then
    raise exception 'Guardian access required';
  end if;

  select cp.household_id
    into v_household_id
  from public.child_profiles cp
  where cp.id=p_child_profile_id and cp.status='active'
  for update;

  if not found then
    raise exception 'Active child profile required';
  end if;

  select *
    into v_join_code
  from private.group_join_codes
  where code_hash=encode(
      extensions.digest(upper(trim(p_code)),'sha256'),'hex'
    )
    and is_active=true
    and expires_at>now()
  for update;

  if not found then
    raise exception 'Join code is invalid, expired, or full';
  end if;

  if not exists(
    select 1
    from public.adventure_groups ag
    join public.organizations o on o.id=ag.organization_id
    where ag.id=v_join_code.group_id
      and ag.status='active'
      and o.status='active'
  ) then
    raise exception 'Group is not active';
  end if;

  -- The child lock serializes joins through different codes and withdrawal.
  -- An already-active membership does not consume another use or rewrite approval.
  if exists (
    select 1 from public.child_group_memberships
    where group_id=v_join_code.group_id and child_profile_id=p_child_profile_id
      and status='active'
  ) then
    return v_join_code.group_id;
  end if;

  if v_join_code.max_uses is not null and v_join_code.use_count>=v_join_code.max_uses then
    raise exception 'Join code is invalid, expired, or full';
  end if;

  select current_policy_version into v_policy_version
  from public.consent_policies
  where consent_key='group_participation' and is_active=true;
  if v_policy_version is null then
    raise exception 'Group participation consent is unavailable';
  end if;

  insert into public.child_group_memberships(
    group_id,child_profile_id,status,
    guardian_approved_by,guardian_approved_at,joined_at
  )
  values(
    v_join_code.group_id,
    p_child_profile_id,
    'active',
    (select auth.uid()),
    now(),
    now()
  )
  on conflict(group_id,child_profile_id) do update
  set status='active',
      guardian_approved_by=(select auth.uid()),
      guardian_approved_at=now(),
      joined_at=now(),
      ended_at=null;

  if v_policy_version is not null
     and not exists (
       select 1
       from public.current_household_consents chc
       where chc.household_id=v_household_id
         and chc.child_profile_id=p_child_profile_id
         and chc.consent_key='group_participation'
         and chc.action='granted'
         and chc.policy_version=v_policy_version
     ) then
    insert into public.household_consents(
      household_id,guardian_user_id,child_profile_id,
      consent_key,action,policy_version,metadata
    )
    values(
      v_household_id,
      (select auth.uid()),
      p_child_profile_id,
      'group_participation',
      'granted',
      v_policy_version,
      jsonb_build_object(
        'surface','group_join',
        'group_id',v_join_code.group_id
      )
    );
  end if;

  update private.group_join_codes
  set use_count=use_count+1
  where id=v_join_code.id;

  v_group_id:=v_join_code.group_id;
  return v_group_id;
end;
$function$;

CREATE OR REPLACE FUNCTION private.notification_audience_count_impl(p_audience_type text, p_membership_plan_id uuid, p_household_id uuid, p_organization_id uuid, p_group_id uuid, p_event_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_count bigint := 0;
begin
  if not private.can_schedule_notifications() then
    return 0;
  end if;

  if p_audience_type='all_guardians' then
    select count(distinct hm.user_id)
      into v_count
    from public.household_members hm
    where hm.status='active'
      and hm.role in ('owner','parent','guardian');

  elsif p_audience_type='plan_guardians' then
    select count(distinct hm.user_id)
      into v_count
    from public.household_subscriptions hs
    join public.household_members hm
      on hm.household_id=hs.household_id
    where hs.plan_id=p_membership_plan_id
      and hs.status in ('trialing','active','comped','past_due')
      and hm.status='active'
      and hm.role in ('owner','parent','guardian');

  elsif p_audience_type='household_guardians' then
    select count(distinct hm.user_id)
      into v_count
    from public.household_members hm
    where hm.household_id=p_household_id
      and hm.status='active'
      and hm.role in ('owner','parent','guardian');

  elsif p_audience_type='group_guardians' then
    select count(distinct hm.user_id)
      into v_count
    from public.child_group_memberships cgm
    join public.child_profiles cp on cp.id=cgm.child_profile_id
    join public.household_members hm on hm.household_id=cp.household_id
    where cgm.group_id=p_group_id
      and cgm.status='active'
      and cp.status='active'
      and hm.status='active'
      and hm.role in ('owner','parent','guardian');

  elsif p_audience_type='organization_guardians' then
    select count(distinct hm.user_id)
      into v_count
    from public.adventure_groups ag
    join public.child_group_memberships cgm on cgm.group_id=ag.id
    join public.child_profiles cp on cp.id=cgm.child_profile_id
    join public.household_members hm on hm.household_id=cp.household_id
    where ag.organization_id=p_organization_id
      and ag.status='active'
      and cgm.status='active'
      and cp.status='active'
      and hm.status='active'
      and hm.role in ('owner','parent','guardian');

  elsif p_audience_type='event_guardians' then
    select count(distinct hm.user_id)
      into v_count
    from public.event_registrations er
    join public.household_members hm on hm.household_id=er.household_id
    where er.event_id=p_event_id
      and er.status in ('registered','waitlist')
      and hm.status='active'
      and hm.role in ('owner','parent','guardian');
  end if;

  return coalesce(v_count,0);
end;
$function$;

CREATE OR REPLACE FUNCTION private.notification_next_delivery_at(p_user_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_timezone text := 'America/Chicago';
  v_start time;
  v_end time;
  v_local_now timestamp;
  v_local_date date;
  v_local_time time;
  v_next_local timestamp;
begin
  select
    coalesce(np.timezone,'America/Chicago'),
    np.quiet_hours_start,
    np.quiet_hours_end
  into v_timezone,v_start,v_end
  from public.notification_preferences np
  where np.user_id=p_user_id;

  if v_start is null or v_end is null or v_start=v_end then
    return now();
  end if;

  v_local_now := timezone(v_timezone,now());
  v_local_date := v_local_now::date;
  v_local_time := v_local_now::time;

  if v_start < v_end then
    if v_local_time >= v_start and v_local_time < v_end then
      v_next_local := v_local_date + v_end;
      return v_next_local at time zone v_timezone;
    end if;
  else
    if v_local_time >= v_start then
      v_next_local := (v_local_date+1) + v_end;
      return v_next_local at time zone v_timezone;
    elsif v_local_time < v_end then
      v_next_local := v_local_date + v_end;
      return v_next_local at time zone v_timezone;
    end if;
  end if;

  return now();
end;
$function$;

CREATE OR REPLACE FUNCTION private.notification_preference_allows(p_user_id uuid, p_notification_type text, p_channel text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select
    case
      when p_channel='email' and not coalesce(np.email_enabled,true) then false
      when p_channel='push' and not coalesce(np.push_enabled,true) then false
      when p_notification_type like 'child_%' and not coalesce(np.child_progress,true) then false
      when p_notification_type like '%badge%' and not coalesce(np.child_progress,true) then false
      when p_notification_type like '%reward%' and not coalesce(np.rewards,true) then false
      when p_notification_type like 'family_%' and not coalesce(np.family_reminders,true) then false
      when p_notification_type like 'product_%' and not coalesce(np.product_updates,true) then false
      when p_notification_type like 'marketing_%' and not coalesce(np.marketing,false) then false
      else true
    end
  from (select p_user_id as user_id) u
  left join public.notification_preferences np on np.user_id=u.user_id;
$function$;

CREATE OR REPLACE FUNCTION private.notify_pending_parent_challenge()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_household_id uuid;
  v_child_name text;
  v_challenge_title text;
begin
  if new.status='pending_parent'
     and (tg_op='INSERT' or old.status is distinct from 'pending_parent') then

    select cp.household_id,cp.display_name,c.title
      into v_household_id,v_child_name,v_challenge_title
    from public.child_profiles cp
    join public.challenges c on c.id=new.challenge_id
    where cp.id=new.child_profile_id;

    insert into public.user_notifications(
      user_id,
      household_id,
      child_profile_id,
      notification_type,
      title,
      body,
      deep_link,
      priority,
      metadata
    )
    select
      hm.user_id,
      v_household_id,
      new.child_profile_id,
      'family_challenge_approval',
      'Challenge ready for your approval',
      coalesce(v_child_name,'Your child')
        || ' finished '
        || coalesce(v_challenge_title,'a challenge')
        || ' and is waiting for guardian approval.',
      '/family',
      'normal',
      jsonb_build_object(
        'challenge_progress_id',new.id,
        'challenge_id',new.challenge_id
      )
    from public.household_members hm
    where hm.household_id=v_household_id
      and hm.status='active'
      and hm.role in ('owner','parent','guardian');
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.notify_reward_unlock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_household_id uuid;
  v_child_name text;
  v_reward_name text;
begin
  select cp.household_id, cp.display_name, r.name
    into v_household_id, v_child_name, v_reward_name
  from public.child_profiles cp
  join public.rewards r on r.id = new.reward_id
  where cp.id = new.child_profile_id;

  insert into public.child_activity_events
    (child_profile_id, household_id, event_type, title, description, source_type, source_id)
  values
    (
      new.child_profile_id,
      v_household_id,
      'reward_unlocked',
      'Reward unlocked',
      v_reward_name,
      'reward',
      new.reward_id
    );

  insert into public.user_notifications
    (user_id, household_id, child_profile_id, notification_type, title, body, deep_link, metadata)
  select
    hm.user_id,
    v_household_id,
    new.child_profile_id,
    'reward_unlocked',
    'A reward was unlocked!',
    coalesce(v_child_name, 'Your child') || ' unlocked ' || v_reward_name || '.',
    '/family/rewards',
    jsonb_build_object('reward_id', new.reward_id, 'reward_unlock_id', new.id)
  from public.household_members hm
  where hm.household_id = v_household_id
    and hm.status = 'active'
    and hm.role in ('owner','parent','guardian');

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.prevent_book_progress_regression()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.status = 'adventure_completed' and new.status <> 'adventure_completed' then
    raise exception 'A completed Book Adventure cannot be restarted';
  end if;

  if old.status = 'completed' and new.status in ('available', 'reading') then
    raise exception 'A completed book cannot be restarted';
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.prevent_completed_progress_reversal()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.status = 'completed' and new.status <> 'completed' and not private.is_app_admin() then
    raise exception 'Completed progress cannot be reversed';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.preview_group_join_code_impl(p_code text)
 RETURNS TABLE(group_id uuid, group_name text, organization_name text, organization_type text, expires_at timestamp with time zone, spots_remaining integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select
    ag.id,
    ag.name,
    o.name,
    o.organization_type,
    gjc.expires_at,
    case
      when gjc.max_uses is null then null
      else greatest(gjc.max_uses-gjc.use_count,0)
    end
  from private.group_join_codes gjc
  join public.adventure_groups ag on ag.id=gjc.group_id
  join public.organizations o on o.id=ag.organization_id
  where gjc.code_hash=encode(extensions.digest(upper(trim(p_code)),'sha256'),'hex')
    and gjc.is_active=true
    and gjc.expires_at>now()
    and (gjc.max_uses is null or gjc.use_count<gjc.max_uses)
    and ag.status='active'
    and o.status='active'
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION private.preview_organization_invitation_impl(p_invitation_id uuid, p_token text)
 RETURNS TABLE(invitation_id uuid, organization_id uuid, organization_name text, organization_type text, organization_role text, group_id uuid, group_name text, group_role text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_email text;
begin
  select lower(email)
    into v_user_email
  from auth.users
  where id=(select auth.uid());

  if v_user_email is null then
    return;
  end if;

  return query
  select
    oi.id,
    oi.organization_id,
    o.name,
    o.organization_type,
    oi.organization_role,
    oi.group_id,
    ag.name,
    oi.group_role,
    oi.expires_at
  from public.organization_invitations oi
  join private.organization_invitation_tokens oit
    on oit.invitation_id=oi.id
  join public.organizations o
    on o.id=oi.organization_id
  left join public.adventure_groups ag
    on ag.id=oi.group_id
  where oi.id=p_invitation_id
    and oi.status='invited'
    and oi.expires_at>now()
    and lower(oi.email)=v_user_email
    and oit.token_hash=encode(
      extensions.digest(trim(p_token),'sha256'),'hex'
    )
    and o.status='active'
  limit 1;
end;
$function$;

CREATE OR REPLACE FUNCTION private.privacy_export_payload_impl(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request public.data_privacy_requests%rowtype;
  v_household jsonb;
  v_children jsonb;
  v_payload jsonb;
begin
  select *
    into v_request
  from public.data_privacy_requests
  where id=p_request_id;

  if not found then
    raise exception 'Privacy request not found';
  end if;

  if not private.can_manage_household(v_request.household_id) then
    raise exception 'Guardian household access required';
  end if;

  if v_request.request_type not in ('export_household','export_child') then
    raise exception 'This request is not a data export';
  end if;

  if v_request.status in ('canceled','rejected') then
    raise exception 'This export request is not active';
  end if;

  select to_jsonb(h)
    into v_household
  from (
    select id,name,status,timezone,created_at,updated_at
    from public.households
    where id=v_request.household_id
  ) h;

  if v_request.request_type='export_child' then
    if v_request.child_profile_id is null then
      raise exception 'Child export request has no child profile';
    end if;

    select jsonb_agg(to_jsonb(cp))
      into v_children
    from (
      select id,household_id,display_name,birth_year,avatar_key,status,created_at,updated_at
      from public.child_profiles
      where id=v_request.child_profile_id
        and household_id=v_request.household_id
    ) cp;
  else
    select coalesce(jsonb_agg(to_jsonb(cp) order by cp.created_at),'[]'::jsonb)
      into v_children
    from (
      select id,household_id,display_name,birth_year,avatar_key,status,created_at,updated_at
      from public.child_profiles
      where household_id=v_request.household_id
    ) cp;
  end if;

  v_payload := jsonb_build_object(
    'export_version','2026.2',
    'generated_at',now(),
    'request_id',v_request.id,
    'request_type',v_request.request_type,
    'household',v_household,
    'children',coalesce(v_children,'[]'::jsonb),
    'guardian_profile',(
      select to_jsonb(p)
      from (
        select id,first_name,last_name,display_name,avatar_url,created_at,updated_at
        from public.profiles
        where id=(select auth.uid())
      ) p
    ),
    'household_members',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at),'[]'::jsonb)
      from (
        select hm.user_id,hm.role,hm.status,hm.created_at,
               p.first_name,p.last_name,p.display_name
        from public.household_members hm
        left join public.profiles p on p.id=hm.user_id
        where hm.household_id=v_request.household_id
      ) x
    ),
    'consents',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at),'[]'::jsonb)
      from (
        select hc.id,hc.guardian_user_id,hc.child_profile_id,hc.consent_key,
               hc.action,hc.policy_version,hc.metadata,hc.created_at
        from public.household_consents hc
        where hc.household_id=v_request.household_id
          and (
            v_request.request_type='export_household'
            or hc.child_profile_id=v_request.child_profile_id
            or hc.child_profile_id is null
          )
      ) x
    ),
    'child_challenge_progress',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at),'[]'::jsonb)
      from public.child_challenge_progress x
      where exists (
        select 1 from public.child_profiles cp
        where cp.id=x.child_profile_id
          and cp.household_id=v_request.household_id
          and (v_request.request_type='export_household' or cp.id=v_request.child_profile_id)
      )
    ),
    'child_adventure_progress',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at),'[]'::jsonb)
      from public.child_adventure_progress x
      where exists (
        select 1 from public.child_profiles cp
        where cp.id=x.child_profile_id
          and cp.household_id=v_request.household_id
          and (v_request.request_type='export_household' or cp.id=v_request.child_profile_id)
      )
    ),
    'scripture_progress',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at),'[]'::jsonb)
      from public.child_scripture_progress x
      where exists (
        select 1 from public.child_profiles cp
        where cp.id=x.child_profile_id
          and cp.household_id=v_request.household_id
          and (v_request.request_type='export_household' or cp.id=v_request.child_profile_id)
      )
    ),
    'devotional_progress',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at),'[]'::jsonb)
      from public.child_devotional_progress x
      where exists (
        select 1 from public.child_profiles cp
        where cp.id=x.child_profile_id
          and cp.household_id=v_request.household_id
          and (v_request.request_type='export_household' or cp.id=v_request.child_profile_id)
      )
    ),
    'prayer_progress',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at),'[]'::jsonb)
      from public.child_prayer_progress x
      where exists (
        select 1 from public.child_profiles cp
        where cp.id=x.child_profile_id
          and cp.household_id=v_request.household_id
          and (v_request.request_type='export_household' or cp.id=v_request.child_profile_id)
      )
    ),
    'identity_progress',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.updated_at),'[]'::jsonb)
      from public.child_identity_progress x
      where exists (
        select 1 from public.child_profiles cp
        where cp.id=x.child_profile_id
          and cp.household_id=v_request.household_id
          and (v_request.request_type='export_household' or cp.id=v_request.child_profile_id)
      )
    ),
    'content_progress',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at),'[]'::jsonb)
      from public.child_content_progress x
      where exists (
        select 1 from public.child_profiles cp
        where cp.id=x.child_profile_id
          and cp.household_id=v_request.household_id
          and (v_request.request_type='export_household' or cp.id=v_request.child_profile_id)
      )
    ),
    'book_progress',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at),'[]'::jsonb)
      from public.child_book_progress x
      where exists (
        select 1 from public.child_profiles cp
        where cp.id=x.child_profile_id
          and cp.household_id=v_request.household_id
          and (v_request.request_type='export_household' or cp.id=v_request.child_profile_id)
      )
    ),
    'book_reading_positions',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.updated_at),'[]'::jsonb)
      from public.child_book_reading_positions x
      where exists (
        select 1 from public.child_profiles cp
        where cp.id=x.child_profile_id
          and cp.household_id=v_request.household_id
          and (v_request.request_type='export_household' or cp.id=v_request.child_profile_id)
      )
    ),
    'xp_ledger',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at),'[]'::jsonb)
      from public.xp_ledger x
      where exists (
        select 1 from public.child_profiles cp
        where cp.id=x.child_profile_id
          and cp.household_id=v_request.household_id
          and (v_request.request_type='export_household' or cp.id=v_request.child_profile_id)
      )
    ),
    'badge_awards',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.awarded_at),'[]'::jsonb)
      from public.badge_awards x
      where exists (
        select 1 from public.child_profiles cp
        where cp.id=x.child_profile_id
          and cp.household_id=v_request.household_id
          and (v_request.request_type='export_household' or cp.id=v_request.child_profile_id)
      )
    ),
    'reward_unlocks',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.unlocked_at),'[]'::jsonb)
      from public.reward_unlocks x
      where exists (
        select 1 from public.child_profiles cp
        where cp.id=x.child_profile_id
          and cp.household_id=v_request.household_id
          and (v_request.request_type='export_household' or cp.id=v_request.child_profile_id)
      )
    ),
    'child_activity',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at),'[]'::jsonb)
      from public.child_activity_events x
      where exists (
        select 1 from public.child_profiles cp
        where cp.id=x.child_profile_id
          and cp.household_id=v_request.household_id
          and (v_request.request_type='export_household' or cp.id=v_request.child_profile_id)
      )
    ),
    'group_memberships',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.joined_at),'[]'::jsonb)
      from public.child_group_memberships x
      where exists (
        select 1 from public.child_profiles cp
        where cp.id=x.child_profile_id
          and cp.household_id=v_request.household_id
          and (v_request.request_type='export_household' or cp.id=v_request.child_profile_id)
      )
    ),
    'event_registrations',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.registered_at),'[]'::jsonb)
      from public.event_registrations x
      where x.household_id=v_request.household_id
        and (
          v_request.request_type='export_household'
          or x.child_profile_id=v_request.child_profile_id
        )
    ),
    'family_faith_sessions',(
      select coalesce(jsonb_agg(to_jsonb(x) order by x.completed_at),'[]'::jsonb)
      from public.household_faith_sessions x
      where x.household_id=v_request.household_id
        and (
          v_request.request_type='export_household'
          or x.child_profile_id=v_request.child_profile_id
        )
    ),
    'orders',case when v_request.request_type='export_household' then (
      select coalesce(jsonb_agg(
        to_jsonb(o) || jsonb_build_object(
          'items',(
            select coalesce(jsonb_agg(to_jsonb(oi) order by oi.created_at),'[]'::jsonb)
            from public.order_items oi where oi.order_id=o.id
          ),
          'fulfillments',(
            select coalesce(jsonb_agg(to_jsonb(f) order by f.created_at),'[]'::jsonb)
            from public.fulfillments f where f.order_id=o.id
          )
        ) order by o.created_at
      ),'[]'::jsonb)
      from public.orders o
      where o.household_id=v_request.household_id
    ) else '[]'::jsonb end,
    'support_tickets',case when v_request.request_type='export_household' then (
      select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at),'[]'::jsonb)
      from public.support_tickets x
      where x.household_id=v_request.household_id
        and x.user_id=(select auth.uid())
    ) else '[]'::jsonb end,
    'requesting_guardian_notifications',case when v_request.request_type='export_household' then (
      select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at),'[]'::jsonb)
      from public.user_notifications x
      where x.user_id=(select auth.uid())
        and (x.household_id=v_request.household_id or x.household_id is null)
    ) else '[]'::jsonb end
  );

  return v_payload;
end;
$function$;

CREATE OR REPLACE FUNCTION private.process_adventure_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_xp integer;
  v_title text;
  v_household_id uuid;
  v_total_xp bigint;
begin
  if new.status <> 'completed' or (tg_op = 'UPDATE' and old.status = 'completed') then
    return new;
  end if;

  select a.completion_xp, a.title, cp.household_id
    into v_xp, v_title, v_household_id
  from public.adventures a
  join public.child_profiles cp on cp.id = new.child_profile_id
  where a.id = new.adventure_id;

  if new.completed_at is null then
    update public.child_adventure_progress
      set completed_at = now()
    where id = new.id and completed_at is null;
  end if;

  if coalesce(v_xp, 0) > 0 then
    insert into public.xp_ledger
      (child_profile_id, points, event_type, source_type, source_id, description)
    values
      (new.child_profile_id, v_xp, 'adventure_completed', 'adventure', new.adventure_id, v_title)
    on conflict do nothing;
  end if;

  insert into public.child_activity_events
    (child_profile_id, household_id, event_type, title, description, source_type, source_id, xp_delta)
  values
    (new.child_profile_id, v_household_id, 'adventure_completed',
     'Adventure completed', v_title, 'adventure', new.adventure_id, coalesce(v_xp,0));

  select coalesce(sum(points), 0)
    into v_total_xp
  from public.xp_ledger
  where child_profile_id = new.child_profile_id;

  insert into public.reward_unlocks
    (child_profile_id, reward_id, unlock_source, source_id)
  select
    new.child_profile_id,
    r.id,
    'xp_threshold',
    new.adventure_id
  from public.rewards r
  where r.is_active = true
    and r.xp_required is not null
    and r.xp_required <= v_total_xp
    and (
      r.access_level in ('free','member')
      or (r.access_level = 'premium' and private.household_has_active_entitlement(v_household_id, 'rewards_redemption'))
    )
  on conflict (child_profile_id, reward_id) do nothing;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.process_book_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_xp integer;
  v_title text;
  v_household_id uuid;
begin
  if new.status not in ('completed','adventure_completed') then
    return new;
  end if;

  if tg_op='UPDATE' and old.status in ('completed','adventure_completed') then
    if old.status='adventure_completed' or new.status=old.status then
      return new;
    end if;
  end if;

  select b.completion_xp, b.title, cp.household_id
    into v_xp, v_title, v_household_id
  from public.books b
  join public.child_profiles cp on cp.id=new.child_profile_id
  where b.id=new.book_id;

  if new.status='completed' and new.completed_at is null then
    update public.child_book_progress
    set completed_at=now()
    where id=new.id and completed_at is null;
  elsif new.status='adventure_completed' and new.adventure_completed_at is null then
    update public.child_book_progress
    set completed_at=coalesce(completed_at,now()),
        adventure_completed_at=now()
    where id=new.id and adventure_completed_at is null;
  end if;

  if new.status='completed' then
    perform private.award_xp_event(
      new.child_profile_id, v_xp, 'book_completed',
      'book', new.book_id, v_title
    );

    insert into public.child_activity_events (
      child_profile_id, household_id, event_type, title, description, source_type, source_id, xp_delta
    )
    values (
      new.child_profile_id, v_household_id, 'book_completed',
      'Book completed', v_title, 'book', new.book_id, coalesce(v_xp,0)
    );
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.process_challenge_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_xp integer;
  v_title text;
  v_household_id uuid;
  v_total_xp bigint;
  v_today date := current_date;
begin
  if new.status <> 'completed' or (tg_op = 'UPDATE' and old.status = 'completed') then
    return new;
  end if;

  select c.xp_reward, c.title, cp.household_id
    into v_xp, v_title, v_household_id
  from public.challenges c
  join public.child_profiles cp on cp.id = new.child_profile_id
  where c.id = new.challenge_id;

  if v_xp is null then
    return new;
  end if;

  if v_xp > 0 then
    insert into public.xp_ledger
      (child_profile_id, points, event_type, source_type, source_id, description)
    values
      (new.child_profile_id, v_xp, 'challenge_completed', 'challenge', new.challenge_id, v_title)
    on conflict do nothing;
  end if;

  insert into public.child_activity_events
    (child_profile_id, household_id, event_type, title, description, source_type, source_id, xp_delta)
  values
    (new.child_profile_id, v_household_id, 'challenge_completed',
     'Challenge completed', v_title, 'challenge', new.challenge_id, v_xp);

  insert into public.child_streaks
    (child_profile_id, streak_key, current_count, best_count, last_activity_date)
  values
    (new.child_profile_id, 'challenge_completion', 1, 1, v_today)
  on conflict (child_profile_id, streak_key) do update
  set current_count =
        case
          when public.child_streaks.last_activity_date = v_today then public.child_streaks.current_count
          when public.child_streaks.last_activity_date = v_today - 1 then public.child_streaks.current_count + 1
          else 1
        end,
      best_count =
        greatest(
          public.child_streaks.best_count,
          case
            when public.child_streaks.last_activity_date = v_today then public.child_streaks.current_count
            when public.child_streaks.last_activity_date = v_today - 1 then public.child_streaks.current_count + 1
            else 1
          end
        ),
      last_activity_date = v_today,
      updated_at = now();

  select coalesce(sum(points), 0)
    into v_total_xp
  from public.xp_ledger
  where child_profile_id = new.child_profile_id;

  insert into public.reward_unlocks
    (child_profile_id, reward_id, unlock_source, source_id)
  select
    new.child_profile_id,
    r.id,
    'xp_threshold',
    new.challenge_id
  from public.rewards r
  where r.is_active = true
    and r.xp_required is not null
    and r.xp_required <= v_total_xp
    and (
      r.access_level in ('free','member')
      or (r.access_level = 'premium' and private.household_has_active_entitlement(v_household_id, 'rewards_redemption'))
    )
  on conflict (child_profile_id, reward_id) do nothing;

  insert into public.user_notifications
    (user_id, household_id, child_profile_id, notification_type, title, body, deep_link, metadata)
  select
    hm.user_id,
    v_household_id,
    new.child_profile_id,
    'child_challenge_completed',
    'Challenge completed!',
    coalesce(cp.display_name, 'Your child') || ' completed ' || v_title || '.',
    '/family/children/' || new.child_profile_id::text,
    jsonb_build_object('challenge_id', new.challenge_id, 'xp_awarded', v_xp)
  from public.household_members hm
  join public.child_profiles cp on cp.id = new.child_profile_id
  where hm.household_id = v_household_id
    and hm.status = 'active'
    and hm.role in ('owner','parent','guardian');

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.process_content_completed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_xp integer;
  v_title text;
  v_household_id uuid;
begin
  if new.status <> 'completed'
     or (tg_op='UPDATE' and old.status='completed') then
    return new;
  end if;

  select ci.completion_xp,ci.title,cp.household_id
    into v_xp,v_title,v_household_id
  from public.content_items ci
  join public.child_profiles cp on cp.id=new.child_profile_id
  where ci.id=new.content_item_id;

  if new.completed_at is null then
    update public.child_content_progress
    set completed_at=now()
    where id=new.id and completed_at is null;
  end if;

  perform private.award_xp_event(
    new.child_profile_id,v_xp,'content_completed',
    'content_item',new.content_item_id,v_title
  );

  insert into public.child_activity_events(
    child_profile_id,household_id,event_type,title,description,source_type,source_id,xp_delta
  )
  values(
    new.child_profile_id,v_household_id,'content_completed',
    'Activity completed',v_title,'content_item',new.content_item_id,coalesce(v_xp,0)
  );

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.process_devotional_completed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_xp integer;
  v_title text;
  v_household_id uuid;
begin
  if new.status <> 'completed'
     or (tg_op='UPDATE' and old.status='completed') then
    return new;
  end if;

  select dd.xp_reward, dd.title, cp.household_id
    into v_xp, v_title, v_household_id
  from public.devotional_days dd
  join public.child_profiles cp on cp.id=new.child_profile_id
  where dd.id=new.devotional_day_id;

  if new.completed_at is null then
    update public.child_devotional_progress
    set completed_at=now()
    where id=new.id and completed_at is null;
  end if;

  perform private.award_xp_event(
    new.child_profile_id, v_xp, 'devotional_completed',
    'devotional_day', new.devotional_day_id, v_title
  );

  insert into public.child_activity_events (
    child_profile_id, household_id, event_type, title, description, source_type, source_id, xp_delta
  )
  values (
    new.child_profile_id, v_household_id, 'devotional_completed',
    'Devotional completed', v_title, 'devotional_day', new.devotional_day_id, coalesce(v_xp,0)
  );

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.process_family_faith_session()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_title text;
begin
  if new.child_profile_id is null then
    return new;
  end if;

  select ffg.title into v_title
  from public.family_faith_guides ffg
  where ffg.id=new.family_faith_guide_id;

  insert into public.child_activity_events (
    child_profile_id,
    household_id,
    event_type,
    title,
    description,
    source_type,
    source_id,
    xp_delta,
    metadata
  )
  values (
    new.child_profile_id,
    new.household_id,
    'family_faith_completed',
    'Family Faith completed',
    v_title,
    'family_faith_guide',
    new.family_faith_guide_id,
    0,
    jsonb_build_object('completed_by',new.completed_by)
  );

  perform private.evaluate_child_badges(new.child_profile_id);

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.process_paid_order_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item record;
  v_rule record;
begin
  if new.status <> 'paid'
     or (tg_op='UPDATE' and old.status='paid') then
    return new;
  end if;

  if new.household_id is null then
    return new;
  end if;

  for v_item in
    select oi.product_id
    from public.order_items oi
    where oi.order_id=new.id
  loop
    for v_rule in
      select pbar.*
      from public.product_book_access_rules pbar
      where pbar.product_id=v_item.product_id
        and pbar.is_active=true
    loop
      insert into public.household_book_access (
        household_id,book_id,source_type,source_id,starts_at,ends_at
      )
      values (
        new.household_id,
        v_rule.book_id,
        'purchase',
        new.id::text,
        now(),
        case when v_rule.duration_days is null then null else now() + make_interval(days=>v_rule.duration_days) end
      )
      on conflict do nothing;
    end loop;

    for v_rule in
      select per.*
      from public.product_entitlement_rules per
      where per.product_id=v_item.product_id
        and per.is_active=true
    loop
      insert into public.household_entitlement_grants (
        household_id,entitlement_key,source_type,source_id,starts_at,ends_at,metadata
      )
      values (
        new.household_id,
        v_rule.entitlement_key,
        'book_bundle',
        new.id::text,
        now(),
        case when v_rule.duration_days is null then null else now() + make_interval(days=>v_rule.duration_days) end,
        jsonb_build_object('product_id',v_item.product_id)
      );
    end loop;
  end loop;

  return new;
end;
$function$;

