$function$;

CREATE OR REPLACE FUNCTION private.process_scripture_memorized()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_xp integer;
  v_title text;
  v_household_id uuid;
begin
  if new.status <> 'memorized'
     or (tg_op='UPDATE' and old.status='memorized') then
    return new;
  end if;

  select pv.memorize_xp, pv.title, cp.household_id
    into v_xp, v_title, v_household_id
  from public.power_verses pv
  join public.child_profiles cp on cp.id=new.child_profile_id
