  perform private.award_xp_event(
    new.child_profile_id, v_xp, 'scripture_memorized',
    'power_verse', new.power_verse_id, v_title
  );

  insert into public.child_activity_events (
    child_profile_id, household_id, event_type, title, description, source_type, source_id, xp_delta
  )
  values (
    new.child_profile_id, v_household_id, 'scripture_memorized',
    'Power Verse memorized', v_title, 'power_verse', new.power_verse_id, coalesce(v_xp,0)
  );

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.process_weekly_series_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_series_id uuid;
  v_period_start date;
  v_period_end date;
  v_token_type text;
  v_token_amount integer;
  v_household_id uuid;
  v_child_name text;
  v_current integer;
  v_best integer;
  v_started date;
  v_last date;
  v_cycle integer;
  v_new_current integer;
  v_new_best integer;
  v_new_started date;
  v_new_cycle integer;
  v_rule record;
  v_earning_id uuid;
begin
  if new.status <> 'completed'
     or (tg_op = 'UPDATE' and old.status = 'completed') then
    return new;
  end if;

  select
    c.challenge_series_id,
    c.period_start,
    c.period_end,
    cs.token_type,
    cs.token_amount,
    cp.household_id,
    cp.display_name
  into
    v_series_id,
    v_period_start,
    v_period_end,
    v_token_type,
    v_token_amount,
    v_household_id,
    v_child_name
  from public.challenges c
  join public.child_profiles cp on cp.id = new.child_profile_id
  left join public.challenge_series cs on cs.id = c.challenge_series_id
  where c.id = new.challenge_id;

  if v_series_id is null or v_period_start is null then
    return new;
  end if;

  insert into public.child_series_weekly_completions (
    child_profile_id,
    challenge_series_id,
    period_start,
    challenge_id,
    progress_id,
    completed_at
  )
  values (
    new.child_profile_id,
    v_series_id,
    v_period_start,
    new.challenge_id,
    new.id,
    coalesce(new.completed_at, now())
  )
  on conflict (child_profile_id, challenge_series_id, period_start) do nothing;

  if not found then
    return new;
  end if;

  insert into public.achievement_token_ledger (
    child_profile_id,
    token_type,
    amount,
    event_type,
    source_type,
    source_id,
    challenge_series_id,
    period_start,
    description
  )
  values (
    new.child_profile_id,
    coalesce(v_token_type, 'weekly_star'),
    coalesce(v_token_amount, 1),
    'weekly_challenge_completed',
    'challenge',
    new.challenge_id,
    v_series_id,
    v_period_start,
    'Weekly challenge completed'
  )
  on conflict do nothing;

  select
    css.current_weeks,
    css.best_weeks,
    css.streak_started_period,
    css.last_completed_period,
    css.current_cycle
  into
    v_current,
    v_best,
    v_started,
    v_last,
    v_cycle
  from public.child_series_streaks css
  where css.child_profile_id = new.child_profile_id
    and css.challenge_series_id = v_series_id
  for update;

  if not found then
    v_new_current := 1;
    v_new_best := 1;
    v_new_started := v_period_start;
    v_new_cycle := 1;
  elsif v_last = v_period_start then
    v_new_current := v_current;
    v_new_best := v_best;
    v_new_started := v_started;
    v_new_cycle := v_cycle;
  elsif v_last = v_period_start - 7 then
    v_new_current := v_current + 1;
    v_new_best := greatest(v_best, v_current + 1);
    v_new_started := v_started;
    v_new_cycle := v_cycle;
  else
    v_new_current := 1;
    v_new_best := greatest(v_best, 1);
    v_new_started := v_period_start;
    v_new_cycle := v_cycle + 1;
  end if;

  insert into public.child_series_streaks (
    child_profile_id,
    challenge_series_id,
    current_weeks,
    best_weeks,
    streak_started_period,
    last_completed_period,
    current_cycle,
    updated_at
  )
  values (
    new.child_profile_id,
    v_series_id,
    v_new_current,
    v_new_best,
    v_new_started,
    v_period_start,
    v_new_cycle,
    now()
  )
  on conflict (child_profile_id, challenge_series_id) do update
  set current_weeks = excluded.current_weeks,
      best_weeks = excluded.best_weeks,
      streak_started_period = excluded.streak_started_period,
      last_completed_period = excluded.last_completed_period,
      current_cycle = excluded.current_cycle,
      updated_at = now();

  for v_rule in
    select sbr.*, b.name as badge_name
    from public.series_badge_rules sbr
    join public.badges b on b.id = sbr.badge_id
    where sbr.challenge_series_id = v_series_id
      and sbr.is_active = true
      and b.is_active = true
      and v_new_current >= sbr.consecutive_weeks_required
  loop
    v_earning_id := null;

    insert into public.streak_badge_earnings (
      child_profile_id,
      challenge_series_id,
      series_badge_rule_id,
      badge_id,
      streak_cycle,
      streak_weeks_at_earn
    )
    values (
      new.child_profile_id,
      v_series_id,
      v_rule.id,
      v_rule.badge_id,
      v_new_cycle,
      v_new_current
    )
    on conflict (child_profile_id, series_badge_rule_id, streak_cycle) do nothing
    returning id into v_earning_id;

    if v_earning_id is not null then
      insert into public.child_activity_events (
        child_profile_id,
        household_id,
        event_type,
        title,
        description,
        source_type,
        source_id
      )
      values (
        new.child_profile_id,
        v_household_id,
        'streak_badge_earned',
        'Streak badge earned',
        v_rule.badge_name,
        'badge',
        v_rule.badge_id
      );

      insert into public.user_notifications (
        user_id,
        household_id,
        child_profile_id,
        notification_type,
        title,
        body,
        deep_link,
        metadata
      )
      select
        hm.user_id,
        v_household_id,
        new.child_profile_id,
        'streak_badge_earned',
        'A streak badge was earned!',
        coalesce(v_child_name, 'Your child') || ' earned the ' || v_rule.badge_name ||
          ' badge after ' || v_rule.consecutive_weeks_required || ' consecutive weeks.',
        '/family/children/' || new.child_profile_id::text || '/badges',
        jsonb_build_object(
          'badge_id', v_rule.badge_id,
          'series_badge_rule_id', v_rule.id,
          'streak_cycle', v_new_cycle,
          'streak_weeks', v_new_current
        )
      from public.household_members hm
      where hm.household_id = v_household_id
        and hm.status = 'active'
        and hm.role in ('owner','parent','guardian');
    end if;
  end loop;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.queue_external_notification_delivery()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_channels jsonb;
  v_next_at timestamptz;
begin
  v_channels := coalesce(
    new.metadata->'delivery_channels',
    '["email","push"]'::jsonb
  );

  v_next_at := private.notification_next_delivery_at(new.user_id);

  insert into public.notification_deliveries(
    notification_id,user_id,channel,status,next_attempt_at
  )
  select new.id,new.user_id,'email','queued',v_next_at
  where v_channels ? 'email'
    and private.notification_preference_allows(
      new.user_id,new.notification_type,'email'
    )
  on conflict(notification_id,channel) do nothing;

  insert into public.notification_deliveries(
    notification_id,user_id,channel,status,next_attempt_at
  )
  select new.id,new.user_id,'push','queued',v_next_at
  where v_channels ? 'push'
    and private.notification_preference_allows(
      new.user_id,new.notification_type,'push'
    )
    and exists (
      select 1
      from public.push_devices pd
      where pd.user_id=new.user_id
        and pd.is_active=true
    )
  on conflict(notification_id,channel) do nothing;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.register_for_event_impl(p_event_id uuid, p_household_id uuid, p_child_profile_id uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_capacity integer;
  v_registered bigint;
  v_status text;
begin
  if (select auth.uid()) is null or not private.can_manage_household(p_household_id) then
    raise exception 'Guardian household access required';
  end if;
  if not private.can_view_event(p_event_id) then
    raise exception 'Event is not available';
  end if;
  if exists (select 1 from public.events where id=p_event_id and access_level='premium')
    and not private.is_app_admin()
    and not private.household_has_active_entitlement(p_household_id,'premium_content')
  then raise exception 'This household requires premium event access'; end if;
  if p_child_profile_id is not null and not exists (
    select 1 from public.child_profiles where id=p_child_profile_id and household_id=p_household_id and status='active'
  ) then raise exception 'Child does not belong to this household'; end if;

  if not private.event_audience_allows_registration(p_event_id,p_household_id,p_child_profile_id) then
    raise exception 'Event is not available for this family selection';
  end if;

  -- All registrations for one event serialize on this row. No roster data is
  -- returned to the caller, even though capacity includes other households.
  select capacity into v_capacity from public.events
  where id=p_event_id and status='published' and starts_at>now() for update;
  if not found then raise exception 'Event registration is closed'; end if;

  select status into v_status from public.event_registrations
  where event_id=p_event_id and household_id=p_household_id
    and child_profile_id is not distinct from p_child_profile_id;
  if found and v_status in ('registered','waitlist','attended') then return v_status; end if;

  select count(*) into v_registered from public.event_registrations
  where event_id=p_event_id and status in ('registered','attended');
  v_status:=case when v_capacity is null or v_registered<v_capacity then 'registered' else 'waitlist' end;
  if p_child_profile_id is null then
    insert into public.event_registrations(event_id,household_id,child_profile_id,registered_by,status)
    values(p_event_id,p_household_id,null,(select auth.uid()),v_status)
    on conflict(event_id,household_id) where child_profile_id is null do update
      set status=excluded.status,registered_by=excluded.registered_by,registered_at=now(),canceled_at=null;
  else
    insert into public.event_registrations(event_id,household_id,child_profile_id,registered_by,status)
    values(p_event_id,p_household_id,p_child_profile_id,(select auth.uid()),v_status)
    on conflict(event_id,child_profile_id) where child_profile_id is not null do update
      set status=excluded.status,registered_by=excluded.registered_by,registered_at=now(),canceled_at=null;
  end if;
  return v_status;
end;
$function$;

CREATE OR REPLACE FUNCTION private.save_digital_book_position_impl(p_child_profile_id uuid, p_book_id uuid, p_revision text, p_page_number integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare content jsonb;
begin
  perform 1 from public.books where id=p_book_id for share;
  if not private.child_has_digital_book_access(p_child_profile_id,p_book_id) or not private.digital_book_released(p_book_id) then
    raise exception 'Digital book access denied' using errcode='42501';
  end if;
  select manifest into content from private.digital_book_manifests where book_id=p_book_id;
  if p_revision is distinct from content->>'revision' or p_page_number is null
    or p_page_number not between 1 and jsonb_array_length(content->'pages') then
    raise exception 'Refresh this book before saving your place' using errcode='22023';
  end if;
  insert into public.child_book_reading_positions(child_profile_id,book_id,revision,page_number)
    values(p_child_profile_id,p_book_id,p_revision,p_page_number)
    on conflict(child_profile_id,book_id) do update set revision=excluded.revision,page_number=excluded.page_number,updated_at=now();
  return p_page_number;
end;
$function$;

CREATE OR REPLACE FUNCTION private.set_guardian_pin_impl(p_household_id uuid, p_pin text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.can_manage_household(p_household_id) then
    raise exception 'Guardian access required';
  end if;

  if p_pin is null or p_pin !~ '^[0-9]{4,6}$' then
    raise exception 'Guardian PIN must be 4 to 6 digits';
  end if;

  insert into private.household_guardian_security (
    household_id, pin_hash, failed_attempts, locked_until, updated_at
  )
  values (
    p_household_id,
    extensions.crypt(p_pin, extensions.gen_salt('bf', 10)),
    0,
    null,
    now()
  )
  on conflict (household_id) do update
  set pin_hash = excluded.pin_hash,
      failed_attempts = 0,
      locked_until = null,
      updated_at = now();
end;
$function$;

CREATE OR REPLACE FUNCTION private.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.sync_reward_redemption_fulfillment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_reward_id uuid;
  v_reward_type text;
  v_inventory integer;
begin
  if new.status = 'fulfilled'
     and old.status is distinct from 'fulfilled' then

    select r.id, r.reward_type, r.inventory_quantity
      into v_reward_id, v_reward_type, v_inventory
    from public.reward_unlocks ru
    join public.rewards r on r.id = ru.reward_id
    where ru.id = new.reward_unlock_id
    for update of r;

    if v_reward_id is null then
      raise exception 'Reward could not be resolved';
    end if;

    if v_reward_type = 'physical' and v_inventory is not null then
      if v_inventory <= 0 then
        raise exception 'Reward is out of stock';
      end if;

      update public.rewards
      set inventory_quantity = inventory_quantity - 1
      where id = v_reward_id;
    end if;

    new.fulfilled_at := coalesce(new.fulfilled_at, now());

    update public.reward_unlocks
      set redeemed_at = coalesce(redeemed_at, now())
    where id = new.reward_unlock_id;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.unlock_book_milestone_rewards()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_milestone text;
begin
  if new.status='completed'
     and (tg_op='INSERT' or old.status not in ('completed','adventure_completed')) then
    v_milestone := 'book_completed';
  elsif new.status='adventure_completed'
     and (tg_op='INSERT' or old.status is distinct from 'adventure_completed') then
    v_milestone := 'adventure_completed';
  else
    return new;
  end if;

  insert into public.reward_unlocks (
    child_profile_id,
    reward_id,
    unlock_source,
    source_id
  )
  select
    new.child_profile_id,
    brr.reward_id,
    'book_' || v_milestone,
    new.book_id
  from public.book_reward_rules brr
  where brr.book_id=new.book_id
    and brr.milestone=v_milestone
    and brr.is_active=true
  on conflict (child_profile_id,reward_id) do nothing;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.user_can_access_challenge(p_challenge_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select private.is_app_admin()
    or exists (
      select 1
      from public.challenges c
      where c.id=p_challenge_id
        and c.status='published'
        and (c.available_from is null or c.available_from<=now())
        and (c.available_until is null or c.available_until>now())
        and (
          c.access_level='free'
          or (c.access_level='member' and private.user_has_household())
          or (
            c.access_level='premium'
            and private.user_has_active_entitlement('full_challenge_library')
          )
        )
    );
$function$;

CREATE OR REPLACE FUNCTION private.user_has_active_entitlement(p_entitlement_key text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select
    exists (
      select 1
      from public.household_members hm
      join public.household_subscriptions hs
        on hs.household_id = hm.household_id
      join public.plan_entitlements pe
        on pe.plan_id = hs.plan_id
      where hm.user_id = (select auth.uid())
        and hm.status = 'active'
        and hs.status in ('trialing','active','comped')
        and (hs.current_period_end is null or hs.current_period_end > now())
        and pe.entitlement_key = p_entitlement_key
    )
    or exists (
      select 1
      from public.household_members hm
      join public.household_entitlement_grants heg
        on heg.household_id = hm.household_id
      where hm.user_id = (select auth.uid())
        and hm.status = 'active'
        and heg.entitlement_key = p_entitlement_key
        and heg.starts_at <= now()
        and (heg.ends_at is null or heg.ends_at > now())
    );
$function$;

CREATE OR REPLACE FUNCTION private.user_has_book_access(p_book_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select
    private.is_app_admin()
    or private.user_has_active_entitlement('book_companions')
    or exists (
      select 1
      from public.household_members hm
      join public.household_book_access hba
        on hba.household_id=hm.household_id
      where hm.user_id=(select auth.uid())
        and hm.status='active'
        and hba.book_id=p_book_id
        and hba.starts_at <= now()
        and (hba.ends_at is null or hba.ends_at > now())
    );
$function$;

