CREATE OR REPLACE FUNCTION public.admin_create_challenge(p_title text, p_slug text, p_challenge_type text, p_description text DEFAULT NULL::text, p_instructions text DEFAULT NULL::text, p_access_level text DEFAULT 'free'::text, p_xp_reward integer DEFAULT 0, p_parent_approval_required boolean DEFAULT false, p_status text DEFAULT 'draft'::text, p_steps jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_challenge_id uuid;
  v_step jsonb;
  v_order integer := 0;
begin
  if not private.is_content_admin() then
    raise exception 'Content administrator access required';
  end if;

  insert into public.challenges (
    title, slug, challenge_type, description, instructions,
    access_level, xp_reward, parent_approval_required, status
  )
  values (
    trim(p_title), trim(p_slug), p_challenge_type, nullif(trim(p_description), ''),
    nullif(trim(p_instructions), ''), p_access_level, greatest(p_xp_reward, 0),
    p_parent_approval_required, p_status
  )
  returning id into v_challenge_id;

  if jsonb_typeof(p_steps) = 'array' then
    for v_step in select value from jsonb_array_elements(p_steps)
    loop
      if nullif(trim(v_step ->> 'title'), '') is not null then
        insert into public.challenge_steps (
          challenge_id,
          title,
          instructions,
          sort_order,
          xp_reward,
          is_required
        )
        values (
          v_challenge_id,
          trim(v_step ->> 'title'),
          nullif(trim(v_step ->> 'instructions'), ''),
          v_order,
          greatest(coalesce((v_step ->> 'xp_reward')::integer, 0), 0),
          coalesce((v_step ->> 'is_required')::boolean, true)
        );
        v_order := v_order + 1;
      end if;
    end loop;
  end if;

  return v_challenge_id;
end;
$function$;

