CREATE OR REPLACE FUNCTION public.admin_create_power_verse(p_scripture_id uuid, p_title text, p_slug text, p_explanation text DEFAULT NULL::text, p_say_it text DEFAULT NULL::text, p_live_it text DEFAULT NULL::text, p_give_it_away text DEFAULT NULL::text, p_memorize_xp integer DEFAULT 0, p_access_level text DEFAULT 'free'::text, p_status text DEFAULT 'draft'::text, p_is_featured boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
  if not private.is_content_admin() then
    raise exception 'Content administrator access required';
  end if;

  insert into public.power_verses(
    scripture_passage_id,title,slug,kid_explanation,say_it,live_it,give_it_away,
    memorize_xp,access_level,status,is_featured
  )
  values(
    p_scripture_id,trim(p_title),trim(p_slug),nullif(trim(p_explanation),''),
    nullif(trim(p_say_it),''),nullif(trim(p_live_it),''),nullif(trim(p_give_it_away),''),
    greatest(p_memorize_xp,0),p_access_level,p_status,p_is_featured
  )
  returning id into v_id;

  return v_id;
end;
$function$;

