CREATE OR REPLACE FUNCTION public.admin_schedule_notification_campaign(p_campaign_key text, p_name text, p_template_id uuid, p_audience_type text, p_scheduled_at timestamp with time zone, p_delivery_channels text[] DEFAULT NULL::text[], p_membership_plan_id uuid DEFAULT NULL::uuid, p_household_id uuid DEFAULT NULL::uuid, p_organization_id uuid DEFAULT NULL::uuid, p_group_id uuid DEFAULT NULL::uuid, p_event_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_template_channels text[];
begin
  if not private.can_schedule_notifications() then
    raise exception 'Notification scheduling access required';
  end if;

  select default_channels
    into v_template_channels
  from public.notification_templates
  where id=p_template_id
    and status='active';

  if v_template_channels is null then
    raise exception 'Notification template must be active and DC-approved before scheduling.';
  end if;

  insert into public.notification_campaigns(
    campaign_key,name,template_id,audience_type,
    membership_plan_id,household_id,organization_id,group_id,event_id,
    delivery_channels,scheduled_at,status,created_by
  )
  values(
    trim(p_campaign_key),
    trim(p_name),
    p_template_id,
    p_audience_type,
    p_membership_plan_id,
    p_household_id,
    p_organization_id,
    p_group_id,
    p_event_id,
    coalesce(p_delivery_channels,v_template_channels),
    p_scheduled_at,
    'scheduled',
    (select auth.uid())
  )
  returning id into v_id;

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_set_order_status(p_order_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not private.is_operations_admin() then
    raise exception 'Operations administrator access required';
  end if;

  update public.orders
  set status=p_status,
      paid_at=case when p_status='paid' then coalesce(paid_at,now()) else paid_at end,
      canceled_at=case when p_status='canceled' then coalesce(canceled_at,now()) else canceled_at end,
      refunded_at=case when p_status='refunded' then coalesce(refunded_at,now()) else refunded_at end
  where id=p_order_id;

  if not found then
    raise exception 'Order not found';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.approve_dc_content_review(p_review_id uuid, p_creative_alignment boolean, p_word_of_faith_alignment boolean, p_scripture_verified boolean, p_identity_in_christ_alignment boolean, p_child_age_appropriate boolean, p_church_affirming boolean, p_approved_assets_only boolean, p_character_continuity boolean, p_language_style_pass boolean, p_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_required_ok boolean;
  v_entity_type text;
  v_entity_id uuid;
  v_fingerprint text;
begin
  if not private.can_approve_dc_governance() then
    raise exception 'DC governance approval access required';
  end if;

  select entity_type,entity_id
    into v_entity_type,v_entity_id
  from public.dc_content_reviews
  where id=p_review_id
  for update;

  if v_entity_type is null then
    raise exception 'Review not found';
  end if;

  v_required_ok :=
    coalesce(p_creative_alignment,false)
    and coalesce(p_word_of_faith_alignment,false)
    and coalesce(p_scripture_verified,false)
    and coalesce(p_identity_in_christ_alignment,false)
    and coalesce(p_child_age_appropriate,false)
    and coalesce(p_church_affirming,false)
    and coalesce(p_approved_assets_only,false)
    and coalesce(p_character_continuity,false)
    and coalesce(p_language_style_pass,false);

  v_fingerprint := private.dc_entity_fingerprint(v_entity_type,v_entity_id);

  update public.dc_content_reviews
  set status=case when v_required_ok then 'approved' else 'changes_requested' end,
      reviewer_user_id=(select auth.uid()),
      reviewed_at=now(),
      creative_alignment=p_creative_alignment,
      word_of_faith_alignment=p_word_of_faith_alignment,
      scripture_verified=p_scripture_verified,
      identity_in_christ_alignment=p_identity_in_christ_alignment,
      child_age_appropriate=p_child_age_appropriate,
      church_affirming=p_church_affirming,
      approved_assets_only=p_approved_assets_only,
      character_continuity=p_character_continuity,
      language_style_pass=p_language_style_pass,
      content_fingerprint=case when v_required_ok then v_fingerprint else null end,
      notes=nullif(trim(p_notes),'')
  where id=p_review_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.approve_parent_challenge(p_progress_id uuid, p_guardian_session_token text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_child_id uuid;
  v_household_id uuid;
  v_status text;
  v_parent_approval boolean;
  v_submitted_at timestamptz;
begin
  select ccp.child_profile_id, cp.household_id, ccp.status,
         c.parent_approval_required, ccp.submitted_at
  into v_child_id, v_household_id, v_status, v_parent_approval, v_submitted_at
  from public.child_challenge_progress ccp
  join public.child_profiles cp on cp.id = ccp.child_profile_id
  join public.challenges c on c.id = ccp.challenge_id
  where ccp.id = p_progress_id;

  if v_child_id is null then
    raise exception 'Challenge progress not found';
  end if;
  if not v_parent_approval then
    raise exception 'This challenge does not require guardian approval';
  end if;
  if v_status <> 'pending_parent' then
    raise exception 'Challenge is not waiting for guardian approval';
  end if;
  if not private.guardian_unlock_session_valid(v_household_id, p_guardian_session_token) then
    raise exception 'Guardian unlock session is invalid or expired';
  end if;

  perform set_config('dc.guardian_approval_verified', 'true', true);
  update public.child_challenge_progress
  set status = 'completed'
  where id = p_progress_id
    and child_profile_id = v_child_id
    and status = 'pending_parent'
    and submitted_at is not distinct from v_submitted_at;
  if not found then
    raise exception 'Challenge changed while being reviewed. Refresh the approval queue.';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.archive_child_profile(p_child_profile_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not private.can_manage_child(p_child_profile_id) then
    raise exception 'Guardian access required';
  end if;

  update public.child_profiles
  set status='archived'
  where id=p_child_profile_id;

  update public.child_group_memberships
  set status='withdrawn',
      ended_at=coalesce(ended_at,now())
  where child_profile_id=p_child_profile_id
    and status='active';

  update public.challenge_assignments
  set status='canceled'
  where child_profile_id=p_child_profile_id
    and status in ('assigned','active');

  if not found and not exists (
    select 1 from public.child_profiles where id=p_child_profile_id
  ) then
    raise exception 'Child profile not found';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.attribute_referral(p_code text, p_referred_household_id uuid, p_source text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  select private.attribute_referral_impl(p_code,p_referred_household_id,p_source);
$function$;

CREATE OR REPLACE FUNCTION public.begin_checkout_provider_handoff(p_checkout_session_id uuid, p_provider text, p_provider_checkout_id text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_order_id uuid;
begin
  if nullif(trim(p_provider),'') is null
     or nullif(trim(p_provider_checkout_id),'') is null then
    raise exception 'Provider and checkout id are required';
  end if;

  select order_id into v_order_id
  from public.checkout_sessions
  where id=p_checkout_session_id
    and user_id=(select auth.uid())
    and status='created'
    and expires_at>now()
  for update;

  if v_order_id is null then
    raise exception 'Checkout session is unavailable or expired';
  end if;

  update public.checkout_sessions
  set status='provider_pending',
      payment_provider=p_provider,
      provider_checkout_id=p_provider_checkout_id,
      updated_at=now()
  where id=p_checkout_session_id;

  update public.orders
  set status='pending_payment',
      payment_provider=p_provider,
      updated_at=now()
  where id=v_order_id
    and status='draft';
end;
$function$;

CREATE OR REPLACE FUNCTION public.cancel_checkout_session(p_checkout_session_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_order_id uuid;
begin
  select order_id into v_order_id
  from public.checkout_sessions
  where id=p_checkout_session_id
    and user_id=(select auth.uid())
    and status in ('created','provider_pending')
  for update;

  if v_order_id is null then raise exception 'Checkout session not found'; end if;

  update public.checkout_sessions
  set status='canceled',updated_at=now()
  where id=p_checkout_session_id;

  update public.inventory_reservations
  set released_at=now()
  where checkout_session_id=p_checkout_session_id
    and released_at is null;

  update public.orders
  set status='canceled',canceled_at=now(),updated_at=now()
  where id=v_order_id
    and status in ('draft','pending_payment');
end;
$function$;

CREATE OR REPLACE FUNCTION public.cancel_data_privacy_request(p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  update public.data_privacy_requests
  set status='canceled'
  where id=p_request_id
    and status in ('requested','identity_confirmed')
    and private.can_manage_household(household_id);

  if not found then
    raise exception 'Request cannot be canceled';
  end if;
end;
$function$;

