$function$;

CREATE OR REPLACE FUNCTION public.claim_notification_deliveries(p_limit integer DEFAULT 50)
 RETURNS TABLE(delivery_id uuid, notification_id uuid, user_id uuid, channel text, attempt_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  return query
  with candidates as (
    select nd.id
    from public.notification_deliveries nd
    where nd.status='queued'
      and nd.next_attempt_at<=now()
    order by nd.created_at
    for update skip locked
    limit greatest(1,least(coalesce(p_limit,50),200))
  ),
  claimed as (
    update public.notification_deliveries nd
    set status='processing',
        attempt_count=nd.attempt_count+1,
        updated_at=now()
    from candidates c
    where nd.id=c.id
    returning nd.id,nd.notification_id,nd.user_id,nd.channel,nd.attempt_count
  )
  select
    c.id,
    c.notification_id,
    c.user_id,
    c.channel,
    c.attempt_count
  from claimed c;
end;
$function$;

CREATE OR REPLACE FUNCTION public.complete_child_book_adventure(p_child_profile_id uuid, p_book_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_ready boolean;
begin
  if not private.can_manage_child(p_child_profile_id) then
    raise exception 'Guardian household access required';
  end if;

  if not private.child_has_book_companion_access(p_child_profile_id,p_book_id) then
    raise exception 'Book companion access required';
  end if;

  select ready_for_adventure_completion
    into v_ready
  from public.get_child_book_adventure_summary(p_child_profile_id,p_book_id);

  if not coalesce(v_ready,false) then
    raise exception 'Required Book Adventure steps are not complete';
  end if;

  insert into public.child_book_progress (
    child_profile_id,book_id,status,started_at,completed_at,adventure_completed_at
  )
  values (
    p_child_profile_id,p_book_id,'adventure_completed',now(),now(),now()
  )
  on conflict (child_profile_id,book_id) do update
  set status='adventure_completed',
      started_at=coalesce(public.child_book_progress.started_at,now()),
      completed_at=coalesce(public.child_book_progress.completed_at,now()),
      adventure_completed_at=coalesce(public.child_book_progress.adventure_completed_at,now());

  perform private.award_completed_book_adventure(p_child_profile_id,p_book_id);

  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.complete_family_faith_participants(p_household_id uuid, p_guide_id uuid, p_child_ids uuid[])
 RETURNS TABLE(child_profile_id uuid, status text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_child uuid; v_ids uuid[];
begin
 if (select auth.uid()) is null or not private.can_manage_household(p_household_id) then
  raise exception 'Guardian household access required'; end if;
 select array_agg(distinct x order by x) into v_ids from unnest(p_child_ids) x;
 if coalesce(cardinality(v_ids),0)=0 or cardinality(v_ids)>100 or array_position(v_ids,null) is not null then
  raise exception 'Choose participating children'; end if;
 if exists(select 1 from unnest(v_ids) x where not exists(select 1 from public.child_profiles cp
   where cp.id=x and cp.household_id=p_household_id and cp.status='active')) then
  raise exception 'Every participant must be an active child in this household'; end if;
 if not exists(select 1 from public.family_faith_guides g where g.id=p_guide_id
   and g.status='published' and (g.available_from is null or g.available_from<=now())
   and (g.available_until is null or g.available_until>now())
   and (g.access_level in ('free','member') or (g.access_level='premium'
     and private.household_has_active_entitlement(p_household_id,'premium_content')))) then
  raise exception 'Family Faith access required'; end if;
 foreach v_child in array v_ids loop
  insert into public.household_faith_sessions(household_id,family_faith_guide_id,child_profile_id,completed_by)
   values(p_household_id,p_guide_id,v_child,(select auth.uid()))
   on conflict on constraint household_faith_sessions_household_id_family_faith_guide_id_key do nothing;
  child_profile_id:=v_child; status:='completed'; return next;
 end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION public.complete_notification_delivery(p_delivery_id uuid, p_status text, p_provider text DEFAULT NULL::text, p_provider_message_id text DEFAULT NULL::text, p_last_error text DEFAULT NULL::text, p_retry_minutes integer DEFAULT NULL::integer, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_status not in ('sent','failed','suppressed','queued') then
    raise exception 'Invalid delivery completion status';
  end if;

  update public.notification_deliveries
  set status=p_status,
      provider=p_provider,
      provider_message_id=p_provider_message_id,
      last_error=p_last_error,
      next_attempt_at=case
        when p_status='queued'
          then now()+make_interval(mins=>greatest(coalesce(p_retry_minutes,5),1))
        else next_attempt_at
      end,
      sent_at=case when p_status='sent' then now() else sent_at end,
      metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb),
      updated_at=now()
  where id=p_delivery_id;

  if not found then
    raise exception 'Delivery not found';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_adventure_group(p_organization_id uuid, p_group_key text, p_name text, p_group_type text DEFAULT 'kids_group'::text, p_description text DEFAULT NULL::text, p_minimum_age smallint DEFAULT NULL::smallint, p_maximum_age smallint DEFAULT NULL::smallint)
 RETURNS uuid
