CREATE OR REPLACE FUNCTION public.dc_preflight_scan(p_entity_type text, p_entity_id uuid)
 RETURNS TABLE(issue_code text, severity text, message text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb;
  v_text text;
  v_prayer text;
  v_missing integer;
begin
  if not private.is_content_admin() then
    raise exception 'Content administrator access required';
  end if;

  v_payload := private.dc_entity_payload(p_entity_type,p_entity_id);

  if v_payload is null then
    return query
      select 'entity_not_found','error','Content record was not found.';
    return;
  end if;

  v_text := v_payload::text;

  if position('—' in v_text) > 0 then
    return query
      select
        'em_dash','error',
        'DC published copy cannot contain an em dash. Replace it with normal punctuation or an en dash.';
  end if;

  if v_text ~* 'Dear[[:space:]]+Jesus([,[:space:]]|$)' then
    return query
      select
        'prayer_to_jesus','error',
        'Dustin Courageous prayers are addressed to God, not Jesus. Begin the prayer with "Dear God,".';
  end if;

  if p_entity_type='prayer_prompt' then
    select prompt_text into v_prayer
    from public.prayer_prompts
    where id=p_entity_id;

    if v_prayer is null
       or btrim(v_prayer) !~* '^Dear[[:space:]]+God[[:space:]]*,' then
      return query
        select
          'prayer_opening','error',
          'Prayer prompts must begin with "Dear God,".';
    end if;

    if not exists (
      select 1
      from public.prayer_prompts
      where id=p_entity_id
        and scripture_passage_id is not null
    ) then
      return query
        select
          'prayer_scripture_link','warning',
          'Consider linking this guided prayer to a verified Scripture passage.';
    end if;
  end if;

  if p_entity_type='family_faith_guide' then
    if not exists (
      select 1
      from public.family_faith_guides
      where id=p_entity_id
        and scripture_passage_id is not null
    ) then
      return query
        select
          'family_scripture','error',
          'Family Faith guides must include a Scripture connection.';
    end if;

    if not exists (
      select 1
      from public.family_faith_guides
      where id=p_entity_id
        and nullif(btrim(discussion_prompt),'') is not null
    ) then
      return query
        select
          'family_discussion','error',
          'Family Faith guides must include a Talk About It discussion prompt.';
    end if;

    select prayer_prompt into v_prayer
    from public.family_faith_guides
    where id=p_entity_id;

    if v_prayer is null
       or btrim(v_prayer) !~* '^Dear[[:space:]]+God[[:space:]]*,' then
      return query
        select
          'family_prayer_opening','error',
          'Family Faith guides must include a prayer that begins with "Dear God,".';
    end if;

    if not exists (
      select 1
      from public.family_faith_guides
      where id=p_entity_id
        and nullif(btrim(family_action),'') is not null
    ) then
      return query
        select
          'family_action','error',
          'Family Faith guides must include a Do It Together family action.';
    end if;
  end if;

  if p_entity_type='power_verse' then
    if not exists (
      select 1
      from public.power_verses
      where id=p_entity_id
        and scripture_passage_id is not null
    ) then
      return query
        select
          'power_verse_scripture','error',
          'A Power Verse must be linked to a verified Scripture passage.';
    end if;

    if exists (
      select 1
      from public.power_verses
      where id=p_entity_id
        and (
          nullif(btrim(say_it),'') is null
          or nullif(btrim(live_it),'') is null
          or nullif(btrim(give_it_away),'') is null
        )
    ) then
      return query
        select
          'power_verse_identity_actions','warning',
          'Power Verses should normally include Say It, Live It, and Give It Away.';
    end if;
  end if;

  if p_entity_type='identity_truth'
     and not exists (
       select 1
       from public.identity_truths
       where id=p_entity_id
         and scripture_passage_id is not null
     ) then
    return query
      select
        'identity_scripture','warning',
        'Identity truths should normally be anchored to a verified Scripture passage.';
  end if;

  if p_entity_type='devotional_series' then
    if not exists (
      select 1
      from public.devotional_days dd
      where dd.devotional_series_id=p_entity_id
    ) then
      return query
        select
          'devotional_days','error',
          'A devotional series must include at least one devotional day.';
    end if;

    select count(*) into v_missing
    from public.devotional_days dd
    where dd.devotional_series_id=p_entity_id
      and dd.prayer_prompt is not null
      and btrim(dd.prayer_prompt) <> ''
      and btrim(dd.prayer_prompt)
        !~* '^Dear[[:space:]]+God[[:space:]]*,';

    if v_missing > 0 then
      return query
        select
          'devotional_prayer_opening','error',
          format(
            '%s devotional prayer(s) do not begin with "Dear God,".',
            v_missing
          );
    end if;

    if exists (
      select 1
      from public.devotional_days dd
      where dd.devotional_series_id=p_entity_id
        and (
          position('—' in coalesce(dd.title,''))>0
          or position('—' in coalesce(dd.body,''))>0
          or position('—' in coalesce(dd.prayer_prompt,''))>0
          or position('—' in coalesce(dd.action_step,''))>0
        )
    ) then
      return query
        select
          'devotional_em_dash','error',
          'One or more devotional days contain an em dash.';
    end if;

    if exists (
      select 1
      from public.devotional_days dd
      where dd.devotional_series_id=p_entity_id
        and dd.scripture_passage_id is null
    ) then
      return query
        select
          'devotional_scripture','warning',
          'One or more devotional days do not have a linked Scripture passage.';
    end if;

    if exists (
      select 1
      from public.devotional_days dd
      where dd.devotional_series_id=p_entity_id
        and nullif(btrim(dd.action_step),'') is null
    ) then
      return query
        select
          'devotional_action','warning',
          'One or more devotional days do not include a practical action step.';
    end if;
  end if;

  if p_entity_type='challenge'
     and not exists (
       select 1
       from public.challenge_steps cs
       where cs.challenge_id=p_entity_id
     ) then
    return query
      select
        'challenge_steps','warning',
        'Adventure Club challenges should normally include at least one concrete challenge step.';
  end if;

  if p_entity_type='book' then
    if not exists (
      select 1 from public.book_power_verses
      where book_id=p_entity_id
    ) then
      return query
        select
          'book_power_verse','warning',
          'The digital Book Adventure should include at least one linked Power Verse.';
    end if;

    if not exists (
      select 1 from public.book_prayer_prompts
      where book_id=p_entity_id
    ) then
      return query
        select
          'book_prayer','warning',
          'The digital Book Adventure should include a linked prayer.';
    end if;

    if not exists (
      select 1 from public.book_identity_truths
      where book_id=p_entity_id
    ) then
      return query
        select
          'book_identity','warning',
          'The digital Book Adventure should include an identity-in-Christ truth.';
    end if;

    if not exists (
      select 1 from public.book_challenges
      where book_id=p_entity_id
    ) then
      return query
        select
          'book_challenge','warning',
          'The digital Book Adventure should include a practical Courage Challenge.';
    end if;
  end if;

  if p_entity_type='notification_template' then
    if not exists (
      select 1
      from public.notification_templates nt
      where nt.id=p_entity_id
        and nullif(btrim(nt.title),'') is not null
        and nullif(btrim(nt.body),'') is not null
    ) then
      return query
        select
          'notification_copy','error',
          'Guardian notification templates require both a title and message body.';
    end if;

    if exists (
      select 1
      from public.notification_templates nt
      where nt.id=p_entity_id
        and nt.notification_type like 'marketing_%'
        and not (nt.default_channels @> array['email']::text[]
                 or nt.default_channels @> array['push']::text[])
    ) then
      return query
        select
          'marketing_delivery','warning',
          'Marketing templates currently have no external delivery channel selected.';
    end if;
  end if;

  if not exists (
    select 1
    from public.dc_governance_standards s
    where s.standard_key='dc-creative-bible'
      and s.version='2026.1'
      and s.is_active=true
      and s.is_locked=true
  ) then
    return query
      select
        'creative_bible_missing','error',
        'The locked Dustin Courageous Bible v2026.1 governance standard is not active.';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.deactivate_app_installation(p_installation_key text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_push_device_id uuid;
begin
  update public.app_installations
  set is_active=false,updated_at=now()
  where user_id=(select auth.uid())
    and installation_key=p_installation_key
  returning push_device_id into v_push_device_id;

  if v_push_device_id is not null then
    update public.push_devices
    set is_active=false,updated_at=now()
    where id=v_push_device_id
      and user_id=(select auth.uid());
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_checkout_readiness()
 RETURNS TABLE(provider_configured boolean, provider_status text, health_status text, message text)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select
    (ip.status in ('configured','active')) as provider_configured,
    ip.status as provider_status,
    ip.health_status,
    case
      when ip.status in ('configured','active') then 'Checkout is ready.'
      else 'Online checkout is not connected yet.'
    end as message
  from public.integration_providers ip
  where ip.provider_key='commerce-primary'
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.get_child_achievement_progress(p_child_profile_id uuid)
 RETURNS TABLE(badge_id uuid, badge_name text, badge_description text, badge_scope text, badge_tier text, badge_family_key text, rule_id uuid, rule_type text, threshold_value integer, current_value bigint, progress_percent integer, earned boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with metrics as (
    select
      br.id as rule_id,
      case br.rule_type
        when 'xp_threshold' then (
          select coalesce(sum(x.points),0)::bigint
          from public.xp_ledger x
          where x.child_profile_id=p_child_profile_id
        )
        when 'challenge_count' then (
          select count(*)::bigint
          from public.child_challenge_progress ccp
          where ccp.child_profile_id=p_child_profile_id and ccp.status='completed'
        )
        when 'adventure_count' then (
          select count(*)::bigint
          from public.child_adventure_progress cap
          where cap.child_profile_id=p_child_profile_id and cap.status='completed'
        )
        when 'streak' then (
          select coalesce(cs.current_count,0)::bigint
          from public.child_streaks cs
          where cs.child_profile_id=p_child_profile_id and cs.streak_key=br.streak_key
          limit 1
        )
        when 'challenge_type_count' then (
          select count(*)::bigint
          from public.child_challenge_progress ccp
          join public.challenges c on c.id=ccp.challenge_id
          where ccp.child_profile_id=p_child_profile_id
            and ccp.status='completed'
            and c.challenge_type=br.challenge_type
        )
        when 'token_threshold' then (
          select coalesce(sum(atl.amount),0)::bigint
          from public.achievement_token_ledger atl
          where atl.child_profile_id=p_child_profile_id
            and atl.token_type=br.token_type
        )
        when 'activity_event_count' then (
          select count(*)::bigint
          from public.child_activity_events cae
          where cae.child_profile_id=p_child_profile_id
            and cae.event_type=br.activity_event_type
        )
        else null
      end as current_value
    from public.badge_rules br
  )
  select
    b.id,
    b.name,
    b.description,
    b.badge_scope,
    b.badge_tier,
    b.badge_family_key,
    br.id,
    br.rule_type,
    br.threshold_value,
    m.current_value,
    case
      when br.rule_type='manual' or br.threshold_value is null then null
      else least(
        100,
        greatest(
          0,
          floor((coalesce(m.current_value,0)::numeric / br.threshold_value::numeric) * 100)
        )
      )::integer
    end,
    exists(
      select 1 from public.badge_awards ba
      where ba.child_profile_id=p_child_profile_id
        and ba.badge_id=b.id
    )
  from public.badges b
  join public.badge_rules br on br.badge_id=b.id and br.is_active=true
  left join metrics m on m.rule_id=br.id
  where b.is_active=true
    and b.badge_scope <> 'streak'
    and private.can_view_child(p_child_profile_id)
  order by
    case when exists(
      select 1 from public.badge_awards ba
      where ba.child_profile_id=p_child_profile_id and ba.badge_id=b.id
    ) then 0 else 1 end,
    coalesce(br.threshold_value,2147483647),
    b.name;
$function$;

CREATE OR REPLACE FUNCTION public.get_child_book_adventure_steps(p_child_profile_id uuid, p_book_id uuid)
 RETURNS TABLE(step_type text, source_id uuid, title text, subtitle text, sort_group integer, sort_order integer, is_required boolean, completed boolean, status text, xp_reward integer)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select *
  from (
    select
      'book'::text as step_type,
      b.id as source_id,
      'Read ' || b.title as title,
      b.subtitle as subtitle,
      0 as sort_group,
      0 as sort_order,
      true as is_required,
      coalesce(cbp.status in ('completed','adventure_completed'), false) as completed,
      coalesce(cbp.status, 'available') as status,
      b.completion_xp as xp_reward
    from public.books b
    left join public.child_book_progress cbp
      on cbp.book_id=b.id and cbp.child_profile_id=p_child_profile_id
    where b.id=p_book_id
      and private.can_view_child(p_child_profile_id)

    union all

    select
      'power_verse',
      pv.id,
      pv.title,
      sp.reference,
      10,
      bpv.sort_order,
      bpv.is_required,
      coalesce(csp.status='memorized',false),
      coalesce(csp.status,'not_started'),
      pv.memorize_xp
    from public.book_power_verses bpv
    join public.power_verses pv on pv.id=bpv.power_verse_id
    left join public.scripture_passages sp on sp.id=pv.scripture_passage_id
    left join public.child_scripture_progress csp
      on csp.power_verse_id=pv.id and csp.child_profile_id=p_child_profile_id
    where bpv.book_id=p_book_id
      and private.can_view_child(p_child_profile_id)

    union all

    select
      'devotional',
      ds.id,
      ds.title,
      (
        select count(*)::text || ' day devotional'
        from public.devotional_days dd
        where dd.devotional_series_id=ds.id
      ),
      20,
      bds.sort_order,
      bds.is_required,
      (
        select count(*) > 0
           and count(*) = count(*) filter (where cdp.status='completed')
        from public.devotional_days dd
        left join public.child_devotional_progress cdp
          on cdp.devotional_day_id=dd.id
         and cdp.child_profile_id=p_child_profile_id
        where dd.devotional_series_id=ds.id
      ),
      case
        when (
          select count(*) > 0
             and count(*) = count(*) filter (where cdp.status='completed')
          from public.devotional_days dd
          left join public.child_devotional_progress cdp
            on cdp.devotional_day_id=dd.id
           and cdp.child_profile_id=p_child_profile_id
          where dd.devotional_series_id=ds.id
        ) then 'completed'
        else 'in_progress'
      end,
      coalesce((
        select sum(dd.xp_reward)::integer
        from public.devotional_days dd
        where dd.devotional_series_id=ds.id
      ),0)
    from public.book_devotional_series bds
    join public.devotional_series ds on ds.id=bds.devotional_series_id
    where bds.book_id=p_book_id
      and private.can_view_child(p_child_profile_id)

    union all

    select
      'identity',
      it.id,
      it.title,
      it.identity_statement,
      30,
      bit.sort_order,
      bit.is_required,
      coalesce(cip.learned,false),
      case when coalesce(cip.learned,false) then 'completed' else 'not_started' end,
      0
    from public.book_identity_truths bit
    join public.identity_truths it on it.id=bit.identity_truth_id
    left join public.child_identity_progress cip
      on cip.identity_truth_id=it.id and cip.child_profile_id=p_child_profile_id
    where bit.book_id=p_book_id
      and private.can_view_child(p_child_profile_id)

    union all

    select
      'prayer',
      pp.id,
      pp.title,
      pp.prompt_text,
      40,
      bpp.sort_order,
      bpp.is_required,
      (cpp.id is not null),
      case when cpp.id is not null then 'completed' else 'not_started' end,
      pp.xp_reward
    from public.book_prayer_prompts bpp
    join public.prayer_prompts pp on pp.id=bpp.prayer_prompt_id
    left join public.child_prayer_progress cpp
      on cpp.prayer_prompt_id=pp.id and cpp.child_profile_id=p_child_profile_id
    where bpp.book_id=p_book_id
      and private.can_view_child(p_child_profile_id)

    union all

    select
      'challenge',
      c.id,
      c.title,
      c.description,
      50,
      bc.sort_order,
      bc.is_required,
      coalesce(ccp.status='completed',false),
      coalesce(ccp.status,'not_started'),
      c.xp_reward
    from public.book_challenges bc
    join public.challenges c on c.id=bc.challenge_id
    left join public.child_challenge_progress ccp
      on ccp.challenge_id=c.id and ccp.child_profile_id=p_child_profile_id
    where bc.book_id=p_book_id
      and private.can_view_child(p_child_profile_id)

    union all

    select
      'activity',
      ci.id,
      ci.title,
      ci.summary,
      60,
      bcl.sort_order,
      bcl.is_required,
      coalesce(ccp.status='completed',false),
      coalesce(ccp.status,'not_started'),
      ci.completion_xp
    from public.book_content_links bcl
    join public.content_items ci on ci.id=bcl.content_item_id
    left join public.child_content_progress ccp
      on ccp.content_item_id=ci.id and ccp.child_profile_id=p_child_profile_id
    where bcl.book_id=p_book_id
      and private.can_view_child(p_child_profile_id)
  ) s
  order by s.sort_group, s.sort_order, s.title;
$function$;

CREATE OR REPLACE FUNCTION public.get_child_book_adventure_summary(p_child_profile_id uuid, p_book_id uuid)
 RETURNS TABLE(total_steps bigint, required_steps bigint, completed_steps bigint, completed_required_steps bigint, progress_percent integer, ready_for_adventure_completion boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with steps as (
    select *
    from public.get_child_book_adventure_steps(p_child_profile_id,p_book_id)
  )
  select
    count(*)::bigint,
    count(*) filter (where is_required)::bigint,
    count(*) filter (where completed)::bigint,
    count(*) filter (where is_required and completed)::bigint,
    case
      when count(*) filter (where is_required)=0 then 0
      else floor(
        (count(*) filter (where is_required and completed)::numeric
        / count(*) filter (where is_required)::numeric) * 100
      )::integer
    end,
    (
      count(*) filter (where is_required) > 0
      and count(*) filter (where is_required)
        = count(*) filter (where is_required and completed)
    )
  from steps;
$function$;

