CREATE OR REPLACE FUNCTION public.publish_dc_entity(p_entity_type text, p_entity_id uuid, p_target_status text DEFAULT 'published'::text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not private.is_content_admin() then
    raise exception 'Content administrator access required';
  end if;

  if not private.has_approved_dc_review(p_entity_type,p_entity_id) then
    raise exception 'A current approved DC governance review is required before publishing.';
  end if;

  case p_entity_type
    when 'book' then
      if p_target_status not in ('coming_soon','published') then raise exception 'Invalid book publish status'; end if;
      update public.books set status=p_target_status where id=p_entity_id;
    when 'adventure' then
      if p_target_status not in ('scheduled','published') then raise exception 'Invalid adventure publish status'; end if;
      update public.adventures set status=p_target_status where id=p_entity_id;
    when 'challenge' then
      if p_target_status not in ('scheduled','published') then raise exception 'Invalid challenge publish status'; end if;
      update public.challenges set status=p_target_status where id=p_entity_id;
    when 'content_item' then
      if p_target_status not in ('scheduled','published') then raise exception 'Invalid content publish status'; end if;
      update public.content_items set status=p_target_status where id=p_entity_id;
    when 'scripture_passage' then
      if p_target_status <> 'published' then raise exception 'Invalid Scripture publish status'; end if;
      update public.scripture_passages set status='published' where id=p_entity_id;
    when 'power_verse' then
      if p_target_status <> 'published' then raise exception 'Invalid Power Verse publish status'; end if;
      update public.power_verses set status='published' where id=p_entity_id;
    when 'devotional_series' then
      if p_target_status not in ('scheduled','published') then raise exception 'Invalid devotional publish status'; end if;
      update public.devotional_series set status=p_target_status where id=p_entity_id;
    when 'prayer_prompt' then
      if p_target_status <> 'published' then raise exception 'Invalid prayer publish status'; end if;
      update public.prayer_prompts set status='published' where id=p_entity_id;
    when 'identity_truth' then
      if p_target_status <> 'published' then raise exception 'Invalid identity truth publish status'; end if;
      update public.identity_truths set status='published' where id=p_entity_id;
    when 'family_faith_guide' then
      if p_target_status not in ('scheduled','published') then raise exception 'Invalid Family Faith publish status'; end if;
      update public.family_faith_guides set status=p_target_status where id=p_entity_id;
    when 'event' then
      if p_target_status <> 'published' then raise exception 'Invalid event publish status'; end if;
      update public.events set status='published' where id=p_entity_id;
    when 'product' then
      if p_target_status <> 'active' then raise exception 'Invalid product publish status'; end if;
      update public.products set status='active' where id=p_entity_id;
    else
      raise exception 'Unsupported DC governance entity type';
  end case;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_household_consent(p_household_id uuid, p_consent_key text, p_action text, p_child_profile_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_policy_version text;
  v_id uuid;
begin
  if not private.can_manage_household(p_household_id) then
    raise exception 'Guardian household access required';
  end if;

  if p_action not in ('granted','revoked') then
    raise exception 'Consent action must be granted or revoked';
  end if;

  select current_policy_version
    into v_policy_version
  from public.consent_policies
  where consent_key=p_consent_key
    and is_active=true;

  if v_policy_version is null then
    raise exception 'Consent policy not found';
  end if;

  if p_child_profile_id is not null and not exists (
    select 1 from public.child_profiles cp
    where cp.id=p_child_profile_id
      and cp.household_id=p_household_id
  ) then
    raise exception 'Child does not belong to this household';
  end if;

  insert into public.household_consents(
    household_id,
    guardian_user_id,
    child_profile_id,
    consent_key,
    action,
    policy_version,
    metadata
  )
  values(
    p_household_id,
    (select auth.uid()),
    p_child_profile_id,
    p_consent_key,
    p_action,
    v_policy_version,
    coalesce(p_metadata,'{}'::jsonb)
  )
  returning id into v_id;

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_integration_event(p_provider_key text, p_event_type text, p_direction text, p_entity_type text, p_entity_id uuid, p_status text, p_idempotency_key text, p_request_payload jsonb DEFAULT '{}'::jsonb, p_response_payload jsonb DEFAULT NULL::jsonb, p_last_error text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_provider_id uuid;
  v_id uuid;
begin
  select id into v_provider_id
  from public.integration_providers
  where provider_key=p_provider_key;

  insert into public.integration_events(
    provider_id,event_type,direction,entity_type,entity_id,status,
    idempotency_key,request_payload,response_payload,last_error,
    processed_at,attempt_count
  )
  values(
    v_provider_id,p_event_type,p_direction,p_entity_type,p_entity_id,p_status,
    nullif(trim(p_idempotency_key),''),
    coalesce(p_request_payload,'{}'::jsonb),
    p_response_payload,p_last_error,
    case when p_status in ('succeeded','failed','ignored') then now() else null end,
    1
  )
  on conflict(idempotency_key) do update
  set status=excluded.status,
      response_payload=excluded.response_payload,
      last_error=excluded.last_error,
      processed_at=excluded.processed_at,
      updated_at=now()
  returning id into v_id;

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.register_app_installation(p_installation_key text, p_app_channel text, p_platform text DEFAULT NULL::text, p_app_version text DEFAULT NULL::text, p_device_name text DEFAULT NULL::text, p_push_provider text DEFAULT NULL::text, p_push_token text DEFAULT NULL::text, p_capabilities jsonb DEFAULT '{}'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := (select auth.uid());
  v_push_device_id uuid;
  v_installation_id uuid;
begin
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  if p_app_channel not in ('web','goodbarber','ios_native','android_native','pwa','other') then
    raise exception 'Unsupported app channel';
  end if;

  if nullif(trim(p_push_token),'') is not null then
    if p_push_provider is null
       or p_push_provider not in ('webpush','goodbarber','apns','fcm','other') then
      raise exception 'Valid push provider required when a push token is supplied';
    end if;

    insert into public.push_devices(
      user_id,provider,device_token,platform,device_name,app_version,is_active,last_seen_at
    )
    values(
      v_user_id,p_push_provider,trim(p_push_token),p_platform,
      nullif(trim(p_device_name),''),nullif(trim(p_app_version),''),true,now()
    )
    on conflict(provider,device_token) do update
    set user_id=v_user_id,
        platform=excluded.platform,
        device_name=excluded.device_name,
        app_version=excluded.app_version,
        is_active=true,
        last_seen_at=now(),
        updated_at=now()
    returning id into v_push_device_id;
  end if;

  insert into public.app_installations(
    user_id,installation_key,app_channel,platform,app_version,device_name,
    push_device_id,is_active,last_seen_at,capabilities,metadata
  )
  values(
    v_user_id,trim(p_installation_key),p_app_channel,p_platform,
    nullif(trim(p_app_version),''),nullif(trim(p_device_name),''),
    v_push_device_id,true,now(),coalesce(p_capabilities,'{}'::jsonb),coalesce(p_metadata,'{}'::jsonb)
  )
  on conflict(user_id,installation_key) do update
  set app_channel=excluded.app_channel,
      platform=excluded.platform,
      app_version=excluded.app_version,
      device_name=excluded.device_name,
      push_device_id=coalesce(excluded.push_device_id,public.app_installations.push_device_id),
      is_active=true,
      last_seen_at=now(),
      capabilities=excluded.capabilities,
      metadata=public.app_installations.metadata||excluded.metadata,
      updated_at=now()
  returning id into v_installation_id;

  return v_installation_id;
end;
$function$;

