CREATE OR REPLACE FUNCTION public.save_family_challenge_participants(p_household_id uuid, p_challenge_id uuid, p_child_ids uuid[], p_action text, p_step_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS TABLE(child_profile_id uuid, status text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_child uuid; v_ids uuid[]; v_progress uuid; v_status text; v_approval boolean;
begin
 if (select auth.uid()) is null or not private.can_manage_household(p_household_id) then
  raise exception 'Guardian household access required'; end if;
 if p_action is null or p_action not in ('participate','complete') then raise exception 'Invalid family action'; end if;
 select array_agg(distinct x order by x) into v_ids from unnest(p_child_ids) x;
 if coalesce(cardinality(v_ids),0)=0 or cardinality(v_ids)>100 or array_position(v_ids,null) is not null then
  raise exception 'Choose participating children'; end if;
 -- Validate the entire selection before any writes. Any later failure also rolls back all children.
 if exists(select 1 from unnest(v_ids) x where not exists(select 1 from public.child_profiles cp
   where cp.id=x and cp.household_id=p_household_id and cp.status='active')
   or not private.child_can_access_challenge(x,p_challenge_id)) then
  raise exception 'Every participant must have access to this challenge in this household'; end if;
 select c.parent_approval_required into v_approval from public.challenges c where c.id=p_challenge_id;
 if not found then raise exception 'Challenge access required'; end if;
 if exists(select 1 from unnest(p_step_ids) x where x is null or not exists(
   select 1 from public.challenge_steps cs where cs.id=x and cs.challenge_id=p_challenge_id)) then
  raise exception 'Invalid challenge step'; end if;
 if p_action='complete' and exists(select 1 from public.challenge_steps cs
   where cs.challenge_id=p_challenge_id and cs.is_required and not(cs.id=any(coalesce(p_step_ids,'{}')))) then
  raise exception 'Confirm every required step for the selected children'; end if;
 foreach v_child in array v_ids loop
  insert into public.child_challenge_progress(child_profile_id,challenge_id,status,started_at)
   values(v_child,p_challenge_id,'in_progress',now())
   on conflict on constraint child_challenge_progress_child_profile_id_challenge_id_key do nothing;
  select p.id,p.status into v_progress,v_status from public.child_challenge_progress p
   where p.child_profile_id=v_child and p.challenge_id=p_challenge_id for update;
  if v_progress is null then raise exception 'Progress could not be confirmed'; end if;
  if v_status not in ('completed','pending_parent') then
   insert into public.child_step_progress(child_challenge_progress_id,challenge_step_id,completed,completed_at)
    select v_progress,x,true,now() from (select distinct unnest(p_step_ids) x) s
    on conflict (child_challenge_progress_id,challenge_step_id) do update set completed=true,completed_at=excluded.completed_at;
   update public.child_challenge_progress p set
    status=case when p_action='complete' then case when v_approval then 'pending_parent' else 'completed' end else 'in_progress' end,
    started_at=coalesce(p.started_at,now()),submitted_at=case when p_action='complete' then now() else p.submitted_at end
    where p.id=v_progress returning p.status into v_status;
  end if;
  child_profile_id:=v_child; status:=v_status; return next;
 end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_guardian_pin(p_household_id uuid, p_pin text)
 RETURNS void
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  select private.set_guardian_pin_impl(p_household_id, p_pin);
$function$;

CREATE OR REPLACE FUNCTION public.update_integration_provider_health(p_provider_key text, p_status text DEFAULT NULL::text, p_health_status text DEFAULT NULL::text, p_success boolean DEFAULT NULL::boolean, p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update public.integration_providers
  set status=coalesce(p_status,status),
      health_status=coalesce(p_health_status,health_status),
      last_health_check_at=now(),
      last_success_at=case when p_success is true then now() else last_success_at end,
      last_error_at=case when p_success is false then now() else last_error_at end,
      last_error=case
        when p_success is true then null
        when p_success is false then p_error
        else last_error
      end,
      updated_at=now()
  where provider_key=p_provider_key;
end;
$function$;

CREATE OR REPLACE FUNCTION public.validate_worker_token(p_token_key text, p_token text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from private.worker_auth_tokens wat
    where wat.token_key=p_token_key
      and wat.is_active=true
      and wat.token_hash=encode(extensions.digest(p_token,'sha256'),'hex')
  );
$function$;

CREATE OR REPLACE FUNCTION public.verify_guardian_pin(p_household_id uuid, p_pin text)
 RETURNS boolean
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  select private.verify_guardian_pin_impl(p_household_id, p_pin);
$function$;

CREATE OR REPLACE FUNCTION public.verify_privacy_cleanup_secret(p_secret text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from private.system_secret_hashes s
    where s.secret_key='privacy_export_cleanup'
      and s.secret_hash=encode(extensions.digest(p_secret,'sha256'),'hex')
  );
$function$;

CREATE OR REPLACE FUNCTION public.withdraw_child_from_group(p_group_id uuid, p_child_profile_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if (select auth.uid()) is null or not private.can_manage_child(p_child_profile_id) then
    raise exception 'Guardian access required';
  end if;
  perform 1 from public.child_profiles where id=p_child_profile_id for update;
  update public.child_group_memberships
  set status='withdrawn',ended_at=coalesce(ended_at,now())
  where group_id=p_group_id and child_profile_id=p_child_profile_id;
  if not found then raise exception 'Group membership not found'; end if;
end;
$function$;


-- Views in dependency order.

CREATE VIEW "public"."admin_daily_metrics" WITH (security_invoker=true) AS
 WITH days AS (
         SELECT generate_series((CURRENT_DATE - 29)::timestamp with time zone, CURRENT_DATE::timestamp with time zone, '1 day'::interval)::date AS metric_date
        )
 SELECT metric_date,
    ( SELECT count(*) AS count
           FROM public.households h
          WHERE h.created_at::date = d.metric_date) AS new_households,
    ( SELECT count(*) AS count
           FROM public.child_profiles cp
          WHERE cp.created_at::date = d.metric_date) AS new_child_profiles,
    ( SELECT count(*) AS count
           FROM public.child_challenge_progress ccp
          WHERE ccp.completed_at::date = d.metric_date AND ccp.status = 'completed'::text) AS challenges_completed,
    ( SELECT count(*) AS count
           FROM public.child_scripture_progress csp
          WHERE csp.memorized_at::date = d.metric_date AND csp.status = 'memorized'::text) AS verses_memorized,
    ( SELECT count(*) AS count
           FROM public.child_book_progress cbp
          WHERE cbp.completed_at::date = d.metric_date AND (cbp.status = ANY (ARRAY['completed'::text, 'adventure_completed'::text]))) AS books_completed,
    ( SELECT count(*) AS count
           FROM public.household_faith_sessions hfs
          WHERE hfs.completed_at::date = d.metric_date) AS family_faith_sessions,
    ( SELECT count(*) AS count
           FROM public.event_registrations er
          WHERE er.registered_at::date = d.metric_date) AS event_registrations,
    ( SELECT count(*) AS count
           FROM public.referral_attributions ra
          WHERE ra.attributed_at::date = d.metric_date) AS referrals_attributed,
    ( SELECT count(*) AS count
           FROM public.orders o
          WHERE o.paid_at::date = d.metric_date AND (o.status = ANY (ARRAY['paid'::text, 'processing'::text, 'partially_fulfilled'::text, 'fulfilled'::text]))) AS paid_orders,
    ( SELECT COALESCE(sum(o.total_cents), 0::bigint) AS "coalesce"
           FROM public.orders o
          WHERE o.paid_at::date = d.metric_date AND (o.status = ANY (ARRAY['paid'::text, 'processing'::text, 'partially_fulfilled'::text, 'fulfilled'::text]))) AS gross_revenue_cents
   FROM days d
  ORDER BY metric_date;

CREATE VIEW "public"."admin_platform_snapshot" WITH (security_invoker=true) AS
 SELECT ( SELECT count(*) AS count
           FROM public.households
          WHERE households.status = 'active'::text) AS active_households,
    ( SELECT count(*) AS count
           FROM public.child_profiles
          WHERE child_profiles.status = 'active'::text) AS active_child_profiles,
    ( SELECT count(*) AS count
           FROM public.household_subscriptions
          WHERE household_subscriptions.status = ANY (ARRAY['trialing'::text, 'active'::text, 'comped'::text])) AS active_subscriptions,
    ( SELECT count(*) AS count
           FROM public.organizations
          WHERE organizations.status = 'active'::text) AS active_organizations,
    ( SELECT count(*) AS count
           FROM public.adventure_groups
          WHERE adventure_groups.status = 'active'::text) AS active_groups,
    ( SELECT count(*) AS count
           FROM public.child_challenge_progress
          WHERE child_challenge_progress.status = 'completed'::text) AS challenges_completed_all_time,
    ( SELECT count(*) AS count
           FROM public.child_scripture_progress
          WHERE child_scripture_progress.status = 'memorized'::text) AS verses_memorized_all_time,
    ( SELECT count(*) AS count
           FROM public.child_book_progress
          WHERE child_book_progress.status = ANY (ARRAY['completed'::text, 'adventure_completed'::text])) AS books_completed_all_time,
    ( SELECT count(*) AS count
           FROM public.reward_unlocks) AS rewards_unlocked_all_time,
    ( SELECT count(*) AS count
           FROM public.support_tickets
          WHERE support_tickets.status <> ALL (ARRAY['resolved'::text, 'closed'::text])) AS open_support_tickets,
    ( SELECT count(*) AS count
           FROM public.data_privacy_requests
          WHERE data_privacy_requests.status <> ALL (ARRAY['completed'::text, 'canceled'::text, 'rejected'::text])) AS open_privacy_requests;

CREATE VIEW "public"."app_channel_health" WITH (security_invoker=true) AS
 SELECT app_channel,
    platform,
    count(*) FILTER (WHERE is_active) AS active_installations,
    count(*) FILTER (WHERE is_active AND push_device_id IS NOT NULL) AS push_ready_installations,
    max(last_seen_at) AS last_seen_at
   FROM public.app_installations ai
  GROUP BY app_channel, platform;

CREATE VIEW "public"."app_installation_summary" WITH (security_invoker=true) AS
 SELECT user_id,
    app_channel,
    platform,
    count(*) FILTER (WHERE is_active) AS active_installations,
    max(last_seen_at) AS last_seen_at,
    count(*) FILTER (WHERE is_active AND push_device_id IS NOT NULL) AS push_enabled_installations
   FROM public.app_installations ai
  GROUP BY user_id, app_channel, platform;

CREATE VIEW "public"."checkout_session_summary" WITH (security_invoker=true) AS
 SELECT cs.id AS checkout_session_id,
    cs.order_id,
    cs.household_id,
    cs.user_id,
    cs.status AS checkout_status,
    cs.payment_provider,
    cs.provider_checkout_id,
    cs.expires_at,
    o.order_number,
    o.status AS order_status,
    o.subtotal_cents,
    o.discount_cents,
    o.shipping_cents,
    o.tax_cents,
    o.total_cents,
    o.currency,
    o.promo_code_id,
    o.created_at
   FROM public.checkout_sessions cs
     JOIN public.orders o ON o.id = cs.order_id;

CREATE VIEW "public"."child_data_inventory" WITH (security_invoker=true) AS
 SELECT id AS child_profile_id,
    household_id,
    display_name,
    status,
    ( SELECT count(*) AS count
           FROM public.child_challenge_progress x
          WHERE x.child_profile_id = cp.id) AS challenge_progress_records,
    ( SELECT count(*) AS count
           FROM public.child_adventure_progress x
          WHERE x.child_profile_id = cp.id) AS adventure_progress_records,
    ( SELECT count(*) AS count
           FROM public.child_scripture_progress x
          WHERE x.child_profile_id = cp.id) AS scripture_progress_records,
    ( SELECT count(*) AS count
           FROM public.child_devotional_progress x
          WHERE x.child_profile_id = cp.id) AS devotional_progress_records,
    ( SELECT count(*) AS count
           FROM public.child_prayer_progress x
          WHERE x.child_profile_id = cp.id) AS prayer_progress_records,
    ( SELECT count(*) AS count
           FROM public.child_identity_progress x
          WHERE x.child_profile_id = cp.id) AS identity_progress_records,
    ( SELECT count(*) AS count
           FROM public.child_content_progress x
          WHERE x.child_profile_id = cp.id) AS content_progress_records,
    ( SELECT count(*) AS count
           FROM public.child_book_progress x
          WHERE x.child_profile_id = cp.id) AS book_progress_records,
    ( SELECT count(*) AS count
           FROM public.xp_ledger x
          WHERE x.child_profile_id = cp.id) AS xp_records,
    ( SELECT count(*) AS count
           FROM public.badge_awards x
          WHERE x.child_profile_id = cp.id) AS badge_records,
    ( SELECT count(*) AS count
           FROM public.reward_unlocks x
          WHERE x.child_profile_id = cp.id) AS reward_records,
    ( SELECT count(*) AS count
           FROM public.child_activity_events x
          WHERE x.child_profile_id = cp.id) AS activity_records,
    ( SELECT count(*) AS count
           FROM public.child_group_memberships x
          WHERE x.child_profile_id = cp.id) AS group_membership_records,
    ( SELECT count(*) AS count
           FROM public.event_registrations x
          WHERE x.child_profile_id = cp.id) AS event_registration_records,
    ( SELECT count(*) AS count
           FROM public.child_book_reading_positions rp
          WHERE rp.child_profile_id = cp.id) AS reading_position_records
   FROM public.child_profiles cp;

CREATE VIEW "public"."child_level_progress" WITH (security_invoker=true) AS
 WITH xp AS (
         SELECT cp.id AS child_profile_id,
            COALESCE(sum(x.points), 0::bigint) AS total_xp
           FROM public.child_profiles cp
             LEFT JOIN public.xp_ledger x ON x.child_profile_id = cp.id
          GROUP BY cp.id
        )
 SELECT xp.child_profile_id,
    xp.total_xp,
    current_level.level_number AS current_level_number,
    current_level.name AS current_level_name,
    current_level.minimum_xp AS current_level_minimum_xp,
    next_level.level_number AS next_level_number,
    next_level.name AS next_level_name,
    next_level.minimum_xp AS next_level_minimum_xp,
        CASE
            WHEN next_level.minimum_xp IS NULL THEN 0::bigint
            ELSE GREATEST(next_level.minimum_xp - xp.total_xp, 0::bigint)
        END AS xp_to_next_level,
        CASE
            WHEN next_level.minimum_xp IS NULL THEN 100
            WHEN current_level.minimum_xp IS NULL THEN 0
            WHEN next_level.minimum_xp = current_level.minimum_xp THEN 100
            ELSE LEAST(100::numeric, GREATEST(0::numeric, round((xp.total_xp - current_level.minimum_xp)::numeric / NULLIF(next_level.minimum_xp - current_level.minimum_xp, 0)::numeric * 100::numeric)))::integer
        END AS level_progress_percent
   FROM xp
     LEFT JOIN LATERAL ( SELECT l.level_number,
            l.name,
            l.minimum_xp
           FROM public.levels l
          WHERE l.is_active = true AND l.minimum_xp <= xp.total_xp
          ORDER BY l.minimum_xp DESC
         LIMIT 1) current_level ON true
     LEFT JOIN LATERAL ( SELECT l.level_number,
            l.name,
            l.minimum_xp
           FROM public.levels l
          WHERE l.is_active = true AND l.minimum_xp > xp.total_xp
          ORDER BY l.minimum_xp
         LIMIT 1) next_level ON true;

CREATE VIEW "public"."child_series_streak_status" WITH (security_invoker=true) AS
 SELECT css.child_profile_id,
    css.challenge_series_id,
    cs.series_key,
    cs.name AS series_name,
    css.best_weeks,
    css.current_cycle,
    css.streak_started_period,
    css.last_completed_period,
        CASE
            WHEN css.last_completed_period IS NULL THEN 0
            WHEN timezone(h.timezone, now())::date <= (css.last_completed_period + 13) THEN css.current_weeks
            ELSE 0
        END AS active_weeks,
    css.last_completed_period IS NOT NULL AND timezone(h.timezone, now())::date <= (css.last_completed_period + 13) AS is_active
   FROM public.child_series_streaks css
     JOIN public.challenge_series cs ON cs.id = css.challenge_series_id
     JOIN public.child_profiles cp ON cp.id = css.child_profile_id
     JOIN public.households h ON h.id = cp.household_id;

CREATE VIEW "public"."child_token_totals" WITH (security_invoker=true) AS
 SELECT child_profile_id,
    token_type,
    COALESCE(sum(amount), 0::bigint) AS total
   FROM public.achievement_token_ledger
  GROUP BY child_profile_id, token_type;

CREATE VIEW "public"."child_xp_totals" WITH (security_invoker=true) AS
 SELECT child_profile_id,
    COALESCE(sum(points), 0::bigint) AS total_xp
   FROM public.xp_ledger
  GROUP BY child_profile_id;

CREATE VIEW "public"."commerce_recent_webhooks" WITH (security_invoker=true) AS
 SELECT id,
    provider,
    provider_event_id,
    event_type,
    order_id,
    status,
    error_message,
    received_at,
    processed_at
   FROM public.payment_webhook_events pwe
  ORDER BY received_at DESC;

CREATE VIEW "public"."current_household_consents" WITH (security_invoker=true) AS
 SELECT DISTINCT ON (hc.household_id, hc.consent_key, (COALESCE(hc.child_profile_id, '00000000-0000-0000-0000-000000000000'::uuid))) hc.id,
    hc.household_id,
    hc.guardian_user_id,
    hc.child_profile_id,
    hc.consent_key,
    cp.title,
    cp.description,
    cp.current_policy_version,
    cp.required_for_core_service,
    cp.applies_to_child,
    hc.action,
    hc.policy_version,
    hc.created_at
   FROM public.household_consents hc
     JOIN public.consent_policies cp ON cp.consent_key = hc.consent_key
  ORDER BY hc.household_id, hc.consent_key, (COALESCE(hc.child_profile_id, '00000000-0000-0000-0000-000000000000'::uuid)), hc.created_at DESC;

